insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d6000000-0000-0000-0000-000000000001', 'mrcp2', '2ef5a163-8c83-481c-af90-311d5a0fec04',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d6000000-0000-0000-0000-000000000001', 'A', 'Switch to intravenous iron replacement (e.g., ferric carboxymaltose)', true, 'Correct. IV iron is preferred when oral iron is poorly tolerated, malabsorbed (e.g., post-ileal resection), or ineffective, and is generally well tolerated in patients with quiescent IBD who have had bleeding excluded.', 1),
('d6000000-0000-0000-0000-000000000001', 'B', 'Increase the oral ferrous sulfate dose further', false, 'Ruled out because tolerance is already limiting oral therapy, and absorption is likely impaired by intestinal resection and ongoing mucosal inflammation; increasing dose will worsen GI side effects without reliably correcting anaemia.', 2),
('d6000000-0000-0000-0000-000000000001', 'C', 'Start an erythropoiesis-stimulating agent without giving iron', false, 'Ruled out because ESA therapy is ineffective without adequate iron stores to support erythropoiesis; the underlying iron deficiency must be corrected first.', 3),
('d6000000-0000-0000-0000-000000000001', 'D', 'Arrange blood transfusion as first-line treatment', false, 'Ruled out because transfusion is not indicated for asymptomatic chronic anaemia of this severity when iron replacement is a safe and effective alternative; transfusion should be reserved for symptomatic or haemodynamically significant anaemia.', 4),
('d6000000-0000-0000-0000-000000000001', 'E', 'Refer for repeat colonoscopy before treating the anaemia further', false, 'Ruled out because active bleeding has already been excluded and disease is quiescent; further endoscopic delay is unnecessary and would only postpone effective treatment.', 5),
('d6000000-0000-0000-0000-000000000002', 'A', 'Increase the prednisolone dose further and continue', false, 'Ruled out because this represents an inadequate response to already high-dose steroid therapy; further dose escalation is unlikely to help and increases toxicity risk.', 1),
('d6000000-0000-0000-0000-000000000002', 'B', 'Proceed directly to splenectomy', false, 'Ruled out because splenectomy is generally reserved for rituximab failure or when rapid definitive control is essential and rituximab is unavailable/contraindicated, not as the immediate next step here.', 2),
('d6000000-0000-0000-0000-000000000002', 'C', 'Add rituximab', true, 'Correct. Rituximab is now favoured as second-line therapy for steroid-refractory or steroid-dependent warm AIHA, with good response rates and a more favourable toxicity profile than splenectomy, and is particularly useful in CLL-associated AIHA.', 3),
('d6000000-0000-0000-0000-000000000002', 'D', 'Switch to azathioprine monotherapy', false, 'Ruled out because azathioprine has a slow onset of action and is not the preferred immediate second-line option for severe, transfusion-dependent steroid-refractory AIHA.', 4),
('d6000000-0000-0000-0000-000000000002', 'E', 'Continue the current regimen unchanged and reassess in 4 weeks', false, 'Ruled out because an inadequate response with ongoing transfusion dependency has already been demonstrated; further watchful waiting delays necessary escalation.', 5),
('d6000000-0000-0000-0000-000000000003', 'A', 'Start oral folic acid first, deferring B12 replacement', false, 'Ruled out because giving folic acid before correcting B12 deficiency can accelerate or worsen the neurological manifestations (subacute combined degeneration) without correcting the underlying metabolic defect.', 1),
('d6000000-0000-0000-0000-000000000003', 'B', 'Start parenteral B12 replacement immediately, before considering folic acid', true, 'Correct. Neurological involvement in B12 deficiency mandates prompt parenteral hydroxocobalamin replacement; B12 must always be corrected before or alongside folate.', 2),
('d6000000-0000-0000-0000-000000000003', 'C', 'Give a single dose of oral B12 and reassess in one month', false, 'Ruled out because oral replacement is inadequate as initial therapy when there is established neurological deficit; parenteral loading is required.', 3),
('d6000000-0000-0000-0000-000000000003', 'D', 'Delay treatment pending further confirmatory autoantibody or Schilling-type testing', false, 'Ruled out because this represents unnecessary delay of treatment for an evolving neurological deficit; intrinsic factor antibody positivity together with the clinical and haematological picture is sufficient to start treatment now.', 4),
('d6000000-0000-0000-0000-000000000003', 'E', 'Start high-dose corticosteroids for the neurological syndrome', false, 'Ruled out because subacute combined degeneration is a direct consequence of B12 deficiency and responds to B12 replacement, not immunosuppression.', 5),
('d6000000-0000-0000-0000-000000000004', 'A', 'Increase the ESA dose further without addressing iron status', false, 'Ruled out because ESA hyporesponsiveness driven by functional iron deficiency will not improve with further dose escalation, which also increases cardiovascular risk.', 1),
('d6000000-0000-0000-0000-000000000004', 'B', 'Withhold iron therapy because ferritin is already elevated', false, 'Ruled out because ferritin elevation in CKD reflects inflammation rather than true iron repletion; TSAT is the more informative marker of functional iron deficiency here.', 2),
('d6000000-0000-0000-0000-000000000004', 'C', 'Switch to oral iron supplementation', false, 'Ruled out because oral iron absorption is poor in dialysis patients due to hepcidin-mediated blockade and reduced gut absorption; IV iron is preferred.', 3),
('d6000000-0000-0000-0000-000000000004', 'D', 'Transfuse red cells to correct the haemoglobin', false, 'Ruled out because transfusion is not indicated for this degree of anaemia in a potential transplant candidate, given the risk of HLA alloimmunisation reducing future transplant compatibility.', 4),
('d6000000-0000-0000-0000-000000000004', 'E', 'Trial intravenous iron despite the elevated ferritin, given the low transferrin saturation', true, 'Correct. In CKD, ferritin is an unreliable marker of true iron stores due to its behaviour as an acute-phase reactant; a TSAT below 20% with ESA hyporesponsiveness supports a trial of IV iron even when ferritin is high.', 5),
('d6000000-0000-0000-0000-000000000005', 'A', 'Simple top-up red cell transfusion alone', false, 'Ruled out because simple transfusion is less effective at rapidly reducing HbS fraction and carries a hyperviscosity risk if Hb rises without lowering the sickle fraction in severe progressive disease.', 1),
('d6000000-0000-0000-0000-000000000005', 'B', 'Increase antibiotic therapy alone and continue current supportive care', false, 'Ruled out because he is actively deteriorating despite supportive measures and requires escalation to transfusion, not antibiotic adjustment alone.', 2),
('d6000000-0000-0000-0000-000000000005', 'C', 'Start hydroxyurea as an acute intervention', false, 'Ruled out because hydroxyurea has no role in acute management of acute chest syndrome; its benefit is in long-term reduction of vaso-occlusive events.', 3),
('d6000000-0000-0000-0000-000000000005', 'D', 'Urgent exchange (erythrocytapheresis) blood transfusion', true, 'Correct. Exchange transfusion is preferred over simple transfusion in severe or progressive acute chest syndrome, as it reduces the percentage of HbS more effectively without excessively raising overall haematocrit/viscosity.', 4),
('d6000000-0000-0000-0000-000000000005', 'E', 'Plan for discharge as he is already on established sickle cell therapy', false, 'Ruled out because he is acutely deteriorating and requires escalation of inpatient care, not discharge.', 5),
('d6000000-0000-0000-0000-000000000006', 'A', 'Continue the current deferasirox dose unchanged since she is asymptomatic', false, 'Ruled out because a T2* under 10 ms signals a high risk of future cardiac dysfunction and arrhythmia that precedes symptoms, requiring proactive chelation intensification rather than continuation of an inadequate regimen.', 1),
('d6000000-0000-0000-0000-000000000006', 'B', 'Discontinue chelation given the liver iron is only mildly elevated', false, 'Ruled out because cardiac and hepatic iron loading can be discordant; cardiac T2* should independently guide chelation intensity regardless of liver iron levels.', 2),
('d6000000-0000-0000-0000-000000000006', 'C', 'Switch to desferrioxamine monotherapy without deferiprone', false, 'Ruled out because deferiprone has particular efficacy in removing cardiac iron compared with desferrioxamine monotherapy, making a deferiprone-containing regimen preferable for significant cardiac iron loading.', 3),
('d6000000-0000-0000-0000-000000000006', 'D', 'Intensify chelation with a deferiprone-based regimen (e.g., combination deferiprone plus desferrioxamine)', true, 'Correct. Cardiac T2* below 10 ms indicates severe myocardial iron loading and requires intensified chelation even in asymptomatic patients; deferiprone has particular efficacy at removing cardiac iron, making deferiprone-based (often combination) regimens preferred here.', 4),
('d6000000-0000-0000-0000-000000000006', 'E', 'Temporarily stop red cell transfusions to reduce further iron loading', false, 'Ruled out because stopping necessary transfusions in thalassaemia major causes severe anaemia and does not address existing iron burden; regular transfusion remains essential.', 5),
('d6000000-0000-0000-0000-000000000007', 'A', 'Start eculizumab immediately without additional precautions', false, 'Ruled out because complement inhibition without appropriate meningococcal prophylaxis carries a significant risk of fulminant meningococcal infection.', 1),
('d6000000-0000-0000-0000-000000000007', 'B', 'Stop anticoagulation before starting eculizumab', false, 'Ruled out because anticoagulation for her prior thrombosis should be continued; there is no indication to stop it before starting complement inhibitor therapy.', 2),
('d6000000-0000-0000-0000-000000000007', 'C', 'Ensure meningococcal vaccination (and consider antibiotic prophylaxis) before starting complement inhibitor therapy', true, 'Correct. Complement (C5) inhibitors markedly increase susceptibility to infection with encapsulated organisms, particularly Neisseria meningitidis; vaccination (ideally at least two weeks prior) and/or antibiotic prophylaxis is mandatory before starting eculizumab.', 3),
('d6000000-0000-0000-0000-000000000007', 'D', 'Proceed to allogeneic stem cell transplant before considering eculizumab', false, 'Ruled out because transplant is reserved for severe aplastic anaemia refractory to or unsuitable for other therapy, not a universal prerequisite before complement inhibition.', 4),
('d6000000-0000-0000-0000-000000000007', 'E', 'Start high-dose corticosteroids as pretreatment', false, 'Ruled out because there is no established role for corticosteroid pretreatment before starting eculizumab.', 5),
('d6000000-0000-0000-0000-000000000008', 'A', 'Continue nitrofurantoin at a reduced dose', false, 'Ruled out because continued exposure to an oxidative trigger will perpetuate ongoing haemolysis.', 1),
('d6000000-0000-0000-0000-000000000008', 'B', 'Start high-dose corticosteroids', false, 'Ruled out because this is not an autoimmune haemolytic process; steroids have no role in drug-induced oxidative haemolysis in G6PD deficiency.', 2),
('d6000000-0000-0000-0000-000000000008', 'C', 'Perform splenectomy', false, 'Ruled out because splenectomy is not indicated for acute, self-limiting drug-induced haemolysis.', 3),
('d6000000-0000-0000-0000-000000000008', 'D', 'Start rituximab', false, 'Ruled out because this is not an autoimmune haemolytic process and rituximab has no role here.', 4),
('d6000000-0000-0000-0000-000000000008', 'E', 'Stop the precipitating drug and provide supportive care, including monitoring for renal impairment and transfusion if severe', true, 'Correct. The mainstay of management for G6PD-related drug-induced oxidative haemolysis is prompt withdrawal of the trigger with supportive care; haemolysis is usually self-limiting once the trigger is removed.', 5),
('d6000000-0000-0000-0000-000000000009', 'A', 'Immunosuppressive therapy with antithymocyte globulin and ciclosporin alone', false, 'Ruled out because this is generally reserved for patients without a matched sibling donor or those unsuitable for transplant; a young fit patient with a matched donor should proceed to transplant.', 1),
('d6000000-0000-0000-0000-000000000009', 'B', 'Allogeneic haematopoietic stem cell transplantation from the matched sibling donor', true, 'Correct. In young patients with severe aplastic anaemia and an available HLA-matched sibling donor, upfront allogeneic stem cell transplantation offers superior long-term survival and cure potential compared with immunosuppressive therapy, and is preferred first-line.', 2),
('d6000000-0000-0000-0000-000000000009', 'C', 'Eltrombopag monotherapy', false, 'Ruled out because eltrombopag is used in combination with immunosuppressive therapy for refractory disease or when transplant is not suitable, not as first-line monotherapy here.', 3),
('d6000000-0000-0000-0000-000000000009', 'D', 'Observation with supportive transfusions only', false, 'Ruled out because severe aplastic anaemia is life-threatening and requires definitive treatment, not observation.', 4),
('d6000000-0000-0000-0000-000000000009', 'E', 'Androgen therapy (e.g., danazol) as first-line treatment', false, 'Ruled out because androgen therapy is a historic option in milder disease or patients unsuitable for transplant/immunosuppression, not first-line in a young fit patient with a matched donor.', 5),
('d6000000-0000-0000-0000-000000000010', 'A', 'Start luspatercept', true, 'Correct. Luspatercept, an erythroid maturation agent, is approved for transfusion-dependent anaemia in lower-risk MDS with ring sideroblasts (SF3B1-mutated) after failure of, or unsuitability for, ESA therapy.', 1),
('d6000000-0000-0000-0000-000000000010', 'B', 'Increase the ESA dose further', false, 'Ruled out because a high baseline erythropoietin level predicts poor response to ESA therapy, making further dose escalation unlikely to help.', 2),
('d6000000-0000-0000-0000-000000000010', 'C', 'Proceed to allogeneic stem cell transplant', false, 'Ruled out because transplant is not an appropriate first step for an elderly patient with lower-risk MDS; it is reserved for higher-risk disease in fit, transplant-eligible patients.', 3),
('d6000000-0000-0000-0000-000000000010', 'D', 'Start intensive AML-type induction chemotherapy', false, 'Ruled out because this is inappropriate for lower-risk, non-transformed MDS.', 4),
('d6000000-0000-0000-0000-000000000010', 'E', 'Start iron chelation alone without addressing the anaemia', false, 'Ruled out because chelation manages iron overload from transfusion but does not address ongoing anaemia or transfusion dependence.', 5),
('d6000000-0000-0000-0000-000000000011', 'A', 'Increase the factor VIII concentrate dose further', false, 'Ruled out because the circulating inhibitor neutralises infused factor VIII, so escalating the dose is ineffective.', 1),
('d6000000-0000-0000-0000-000000000011', 'B', 'Start immune tolerance induction alone without changing bleed prophylaxis', false, 'Ruled out because immune tolerance induction aims to eradicate the inhibitor over months but does not provide immediate bleed protection, so is used alongside alternative prophylaxis, not instead of it.', 2),
('d6000000-0000-0000-0000-000000000011', 'C', 'Switch to recombinant factor IX concentrate', false, 'Ruled out because factor IX is not relevant to haemophilia A and does not address the factor VIII inhibitor.', 3),
('d6000000-0000-0000-0000-000000000011', 'D', 'Start warfarin for long-term prophylaxis', false, 'Ruled out because anticoagulation is inappropriate and dangerous in a patient with an inherited bleeding disorder.', 4),
('d6000000-0000-0000-0000-000000000011', 'E', 'Switch to emicizumab prophylaxis', true, 'Correct. Emicizumab, a bispecific antibody mimicking factor VIII cofactor activity, is effective prophylaxis in haemophilia A patients with inhibitors, as it bypasses the need for factor VIII and is not neutralised by anti-FVIII antibodies.', 5),
('d6000000-0000-0000-0000-000000000012', 'A', 'DDAVP is ineffective in all types of von Willebrand disease', false, 'Ruled out because DDAVP is effective and commonly used in type 1 and many non-2B type 2 VWD.', 1),
('d6000000-0000-0000-0000-000000000012', 'B', 'DDAVP causes clinically significant hypertension in VWD patients', false, 'Ruled out because this is not the mechanism of concern in type 2B disease; the key issue is platelet aggregation from released abnormal VWF.', 2),
('d6000000-0000-0000-0000-000000000012', 'C', 'DDAVP increases the risk of anaphylaxis in VWD', false, 'Ruled out because this is not the recognised contraindication in type 2B VWD.', 3),
('d6000000-0000-0000-0000-000000000012', 'D', 'DDAVP can release the abnormal high-affinity VWF, causing platelet aggregation/clumping and worsening thrombocytopenia', true, 'Correct. In type 2B VWD, the mutant VWF has increased affinity for platelet GPIb, so DDAVP-induced VWF release can cause platelet aggregation and paradoxically worsen thrombocytopenia; DDAVP is therefore generally contraindicated.', 4),
('d6000000-0000-0000-0000-000000000012', 'E', 'DDAVP has no role in any bleeding disorder and is used only for diabetes insipidus', false, 'Ruled out because DDAVP has an established role in VWD and mild haemophilia A through release of endogenous VWF and factor VIII.', 5),
('d6000000-0000-0000-0000-000000000013', 'A', 'Use bypassing agents (recombinant activated factor VII or activated prothrombin complex concentrate) for acute bleeding, alongside immunosuppression to eradicate the inhibitor', true, 'Correct. Acquired haemophilia A results from autoantibodies against factor VIII; bypassing agents control acute bleeding because factor VIII concentrate is neutralised by the inhibitor, while immunosuppression (e.g., corticosteroids plus rituximab or cyclophosphamide) is needed to eradicate the antibody.', 1),
('d6000000-0000-0000-0000-000000000013', 'B', 'Give high-dose factor VIII concentrate alone', false, 'Ruled out because the circulating inhibitor will neutralise infused factor VIII, making it ineffective for controlling bleeding.', 2),
('d6000000-0000-0000-0000-000000000013', 'C', 'Treat with vitamin K', false, 'Ruled out because PT is normal, indicating this is not a vitamin K-dependent factor deficiency.', 3),
('d6000000-0000-0000-0000-000000000013', 'D', 'Treat with desmopressin alone', false, 'Ruled out because DDAVP raises endogenous factor VIII/VWF only modestly and is inadequate for an inhibitor-mediated severe factor VIII deficiency.', 4),
('d6000000-0000-0000-0000-000000000013', 'E', 'Observe without treatment, as most cases self-resolve', false, 'Ruled out because acquired haemophilia A is life-threatening and requires prompt haemostatic and immunosuppressive treatment.', 5),
('d6000000-0000-0000-0000-000000000014', 'A', 'Start therapeutic-dose heparin infusion', false, 'Ruled out because anticoagulation is inappropriate in bleeding DIC; heparin has a limited role reserved for cases with predominant thrombotic manifestations without significant bleeding.', 1),
('d6000000-0000-0000-0000-000000000014', 'B', 'Give tranexamic acid alone as sole treatment', false, 'Ruled out because antifibrinolytics are generally avoided or used with great caution in DIC due to the risk of promoting pathological thrombus formation, and are not sufficient as sole treatment for active surgical bleeding.', 2),
('d6000000-0000-0000-0000-000000000014', 'C', 'Treat the underlying sepsis aggressively and give targeted blood component replacement (FFP, cryoprecipitate for low fibrinogen, platelet transfusion) guided by bleeding and laboratory parameters', true, 'Correct. DIC management centres on treating the underlying trigger alongside targeted replacement of consumed clotting factors, fibrinogen, and platelets guided by bleeding severity and laboratory trend.', 3),
('d6000000-0000-0000-0000-000000000014', 'D', 'Withhold blood products until fibrinogen and platelet counts normalise spontaneously', false, 'Ruled out because active bleeding coagulopathy requires prompt correction of deficient factors and platelets, not watchful waiting.', 4),
('d6000000-0000-0000-0000-000000000014', 'E', 'Start warfarin', false, 'Ruled out because warfarin is inappropriate for acute coagulopathy, takes days to act, and is contraindicated with active bleeding.', 5),
('d6000000-0000-0000-0000-000000000015', 'A', 'IV vitamin K alone, awaiting effect over 24 hours', false, 'Ruled out because this is too slow for life-threatening bleeding; PCC provides immediate factor replacement that vitamin K alone cannot.', 1),
('d6000000-0000-0000-0000-000000000015', 'B', 'IV vitamin K plus 4-factor prothrombin complex concentrate', true, 'Correct. Life-threatening warfarin-associated bleeding requires rapid reversal with 4-factor PCC, replacing factors II, VII, IX and X immediately, combined with IV vitamin K to sustain reversal and prevent rebound coagulopathy.', 2),
('d6000000-0000-0000-0000-000000000015', 'C', 'Fresh frozen plasma alone without vitamin K', false, 'Ruled out because FFP is slower to prepare and infuse, requires a larger volume, and provides less complete/rapid reversal than PCC; vitamin K is still needed to sustain reversal.', 3),
('d6000000-0000-0000-0000-000000000015', 'D', 'Protamine sulfate', false, 'Ruled out because protamine reverses heparin, not warfarin.', 4),
('d6000000-0000-0000-0000-000000000015', 'E', 'Idarucizumab', false, 'Ruled out because idarucizumab reverses dabigatran, not warfarin.', 5),
('d6000000-0000-0000-0000-000000000016', 'A', 'Andexanet alfa (or 4-factor PCC if unavailable)', true, 'Correct. Andexanet alfa is a specific reversal agent for factor Xa inhibitors such as apixaban and rivaroxaban; where unavailable, 4-factor PCC is used as an alternative for major bleeding.', 1),
('d6000000-0000-0000-0000-000000000016', 'B', 'Idarucizumab', false, 'Ruled out because idarucizumab is specific for dabigatran, a direct thrombin inhibitor, and has no effect on factor Xa inhibitors such as apixaban.', 2),
('d6000000-0000-0000-0000-000000000016', 'C', 'Protamine sulfate', false, 'Ruled out because protamine reverses heparin, not apixaban.', 3),
('d6000000-0000-0000-0000-000000000016', 'D', 'Fresh frozen plasma alone', false, 'Ruled out because FFP is not an effective specific reversal strategy for factor Xa inhibitors.', 4),
('d6000000-0000-0000-0000-000000000016', 'E', 'Vitamin K', false, 'Ruled out because apixaban does not act through vitamin K-dependent factors, so vitamin K has no role.', 5),
('d6000000-0000-0000-0000-000000000017', 'A', 'Repeat IVIG indefinitely as maintenance therapy', false, 'Ruled out because IVIG produces only a transient response and is not a sustainable long-term maintenance strategy.', 1),
('d6000000-0000-0000-0000-000000000017', 'B', 'Proceed to splenectomy despite her declining it', false, 'Ruled out because treatment cannot proceed against patient wishes; a TPO receptor agonist is an appropriate alternative when splenectomy is declined.', 2),
('d6000000-0000-0000-0000-000000000017', 'C', 'Continue high-dose corticosteroids long-term', false, 'Ruled out because long-term high-dose steroids carry significant toxicity and are not an appropriate maintenance strategy.', 3),
('d6000000-0000-0000-0000-000000000017', 'D', 'Observe without further treatment given low bleeding risk', false, 'Ruled out because a platelet count of 8 with active mucosal bleeding is high risk and requires escalation of treatment.', 4),
('d6000000-0000-0000-0000-000000000017', 'E', 'Start a thrombopoietin receptor agonist (e.g., eltrombopag or romiplostim)', true, 'Correct. TPO receptor agonists are effective second-line options for chronic ITP refractory to or relapsing after corticosteroids, particularly when splenectomy is declined or deferred.', 5),
('d6000000-0000-0000-0000-000000000018', 'A', 'Platelet transfusion as first-line treatment', false, 'Ruled out because platelet transfusion is generally avoided in TTP outside life-threatening bleeding, as it may fuel microvascular thrombosis and worsen organ ischaemia.', 1),
('d6000000-0000-0000-0000-000000000018', 'B', 'Await the ADAMTS13 result before starting any treatment', false, 'Ruled out because TTP carries high mortality if untreated, and treatment should not be delayed pending confirmatory testing when clinical suspicion is high.', 2),
('d6000000-0000-0000-0000-000000000018', 'C', 'Urgent plasma exchange, with consideration of caplacizumab and corticosteroids/rituximab', true, 'Correct. TTP is a haematological emergency requiring urgent plasma exchange without waiting for confirmatory ADAMTS13 results when clinical suspicion is high (e.g., a high PLASMIC score); caplacizumab and immunosuppression are increasingly used alongside plasma exchange.', 3),
('d6000000-0000-0000-0000-000000000018', 'D', 'Start therapeutic anticoagulation', false, 'Ruled out because anticoagulation has no established role in initial acute TTP management and does not address the ADAMTS13-mediated microthrombotic process.', 4),
('d6000000-0000-0000-0000-000000000018', 'E', 'Start vitamin K', false, 'Ruled out because the coagulation screen is normal; this is not a clotting factor deficiency.', 5),
('d6000000-0000-0000-0000-000000000019', 'A', 'Continue heparin at a reduced dose', false, 'Ruled out because any heparin exposure must be stopped in suspected HIT due to ongoing platelet activation and thrombosis risk.', 1),
('d6000000-0000-0000-0000-000000000019', 'B', 'Stop all heparin products and start a non-heparin anticoagulant (e.g., argatroban or fondaparinux)', true, 'Correct. Heparin-induced thrombocytopenia requires immediate cessation of all heparin products, including LMWH due to cross-reactivity, and initiation of an alternative non-heparin anticoagulant.', 2),
('d6000000-0000-0000-0000-000000000019', 'C', 'Switch to LMWH instead of unfractionated heparin', false, 'Ruled out because cross-reactivity with HIT antibodies means LMWH is not a safe alternative.', 3),
('d6000000-0000-0000-0000-000000000019', 'D', 'Start warfarin immediately as monotherapy', false, 'Ruled out because warfarin should not be started until the platelet count has substantially recovered, as it can precipitate venous limb gangrene or skin necrosis from acute protein C depletion in the pro-thrombotic HIT state.', 4),
('d6000000-0000-0000-0000-000000000019', 'E', 'Give platelet transfusion to correct the thrombocytopenia', false, 'Ruled out because platelet transfusion is generally avoided in HIT as it may fuel further thrombosis, and is reserved only for significant bleeding.', 5),
('d6000000-0000-0000-0000-000000000020', 'A', 'Switch to rivaroxaban for improved compliance', false, 'Ruled out because rivaroxaban has shown inferior efficacy with higher recurrent thrombosis rates in triple-positive APS compared with warfarin.', 1),
('d6000000-0000-0000-0000-000000000020', 'B', 'Switch to dabigatran', false, 'Ruled out because dabigatran is similarly not recommended in high-risk APS, with trial data showing inferiority to warfarin in this population.', 2),
('d6000000-0000-0000-0000-000000000020', 'C', 'Stop anticoagulation given the recurrent event suggests treatment failure', false, 'Ruled out because recurrent thrombosis on adequate anticoagulation should prompt optimisation, such as reassessing adherence or increasing the INR target, not cessation of anticoagulation.', 3),
('d6000000-0000-0000-0000-000000000020', 'D', 'DOACs should be avoided in triple-positive APS with prior thrombosis; she should remain on, or be optimised on, warfarin, with consideration of a higher-intensity target if recurrence continues', true, 'Correct. Trial evidence demonstrates higher rates of recurrent thrombotic events, particularly arterial, with DOACs compared with vitamin K antagonist therapy in triple-positive APS, so warfarin remains preferred and should be optimised rather than switched.', 4),
('d6000000-0000-0000-0000-000000000020', 'E', 'Switch to aspirin monotherapy', false, 'Ruled out because aspirin monotherapy is inadequate anticoagulation intensity for secondary prevention of thrombosis in APS with prior venous and arterial events.', 5),
('d6000000-0000-0000-0000-000000000021', 'A', 'Switch to dasatinib', false, 'Ruled out because T315I confers resistance to dasatinib as well as imatinib and nilotinib.', 1),
('d6000000-0000-0000-0000-000000000021', 'B', 'Ponatinib (or asciminib)', true, 'Correct. The T315I gatekeeper mutation confers resistance to imatinib and most second-generation TKIs; ponatinib, a third-generation TKI, and asciminib, an allosteric STAMP inhibitor, retain activity against this mutation.', 2),
('d6000000-0000-0000-0000-000000000021', 'C', 'Increase the imatinib dose', false, 'Ruled out because the resistance mutation renders dose escalation ineffective.', 3),
('d6000000-0000-0000-0000-000000000021', 'D', 'Switch to nilotinib', false, 'Ruled out because nilotinib is also ineffective against T315I.', 4),
('d6000000-0000-0000-0000-000000000021', 'E', 'Stop TKI therapy and monitor off treatment', false, 'Ruled out because active resistant disease requires escalation of therapy, not cessation.', 5),
('d6000000-0000-0000-0000-000000000022', 'A', 'Stop ATRA and arsenic trioxide permanently', false, 'Ruled out because differentiation syndrome is corticosteroid-responsive and treatment is usually continued (with only temporary interruption if severe), not permanently stopped.', 1),
('d6000000-0000-0000-0000-000000000022', 'B', 'Start broad-spectrum antibiotics alone without steroids, presuming sepsis', false, 'Ruled out because although infection should be covered empirically, this clinical picture on ATRA/ATO is classic for differentiation syndrome, which requires prompt corticosteroids.', 2),
('d6000000-0000-0000-0000-000000000022', 'C', 'Start high-dose dexamethasone promptly and continue ATRA/arsenic unless the presentation is life-threatening, in which case temporarily withhold them', true, 'Correct. Differentiation syndrome presents with fever, dyspnoea, pulmonary infiltrates, weight gain and hypotension, and is treated promptly with high-dose corticosteroids; ATRA/ATO are usually continued unless the syndrome is severe.', 3),
('d6000000-0000-0000-0000-000000000022', 'D', 'Give urgent chemotherapy cytoreduction', false, 'Ruled out because this is not the immediate management for differentiation syndrome, which is corticosteroid-responsive.', 4),
('d6000000-0000-0000-0000-000000000022', 'E', 'Perform urgent leukapheresis', false, 'Ruled out because leukapheresis is not the primary treatment for differentiation syndrome and is relatively contraindicated in APL given the high risk of bleeding/coagulopathy.', 5),
('d6000000-0000-0000-0000-000000000023', 'A', 'This represents simple CLL progression; escalate to standard CLL-directed therapy alone', false, 'Ruled out because the histological transformation to an aggressive high-grade lymphoma requires DLBCL-type treatment, not standard CLL therapy alone.', 1),
('d6000000-0000-0000-0000-000000000023', 'B', 'Reassure and continue watch-and-wait given the known CLL diagnosis', false, 'Ruled out because asymmetric rapid nodal growth with systemic symptoms and raised LDH is a red flag requiring biopsy and prompt treatment, not observation.', 2),
('d6000000-0000-0000-0000-000000000023', 'C', 'Start a course of oral corticosteroids for a presumed autoimmune flare', false, 'Ruled out because this is a lymphoma transformation requiring specific chemoimmunotherapy, not an autoimmune process.', 3),
('d6000000-0000-0000-0000-000000000023', 'D', 'Refer directly for palliative care given the transformation', false, 'Ruled out because although transformation carries a poorer prognosis, active treatment with chemoimmunotherapy (and transplant consolidation if fit) is still first-line.', 4),
('d6000000-0000-0000-0000-000000000023', 'E', 'This represents Richter transformation; treat with DLBCL-type chemoimmunotherapy (e.g., R-CHOP) and consider clonal relatedness testing to guide prognosis', true, 'Correct. Richter transformation refers to CLL evolving into an aggressive lymphoma, usually DLBCL, suggested by asymmetric rapid lymphadenopathy, systemic B symptoms, and markedly raised LDH, and requires aggressive lymphoma-type treatment.', 5),
('d6000000-0000-0000-0000-000000000024', 'A', 'Midostaurin (or another FLT3 inhibitor such as gilteritinib in the relapsed setting)', true, 'Correct. FLT3-ITD mutations, particularly with a high allelic ratio, confer an adverse prognosis; addition of the FLT3 inhibitor midostaurin to induction and consolidation chemotherapy improves survival.', 1),
('d6000000-0000-0000-0000-000000000024', 'B', 'Rituximab', false, 'Ruled out because rituximab targets CD20 relevant in B-cell lymphomas, not myeloid AML blasts.', 2),
('d6000000-0000-0000-0000-000000000024', 'C', 'Imatinib', false, 'Ruled out because imatinib targets BCR-ABL, relevant in CML/Ph+ ALL, not FLT3-mutated AML.', 3),
('d6000000-0000-0000-0000-000000000024', 'D', 'All-trans retinoic acid', false, 'Ruled out because ATRA is specific to APL (PML-RARA), not FLT3-mutated non-APL AML.', 4),
('d6000000-0000-0000-0000-000000000024', 'E', 'No additional targeted therapy is warranted; standard chemotherapy alone is sufficient', false, 'Ruled out because FLT3-ITD with a high allelic ratio confers adverse prognosis, and addition of a FLT3 inhibitor improves outcomes.', 5),
('d6000000-0000-0000-0000-000000000025', 'A', 'Repeat ABVD chemotherapy', false, 'Ruled out because relapse within 12 months of first-line ABVD indicates the need for a salvage regimen and transplant consolidation, not repetition of the same regimen.', 1),
('d6000000-0000-0000-0000-000000000025', 'B', 'Radiotherapy alone', false, 'Ruled out because radiotherapy alone is insufficient for relapsed systemic disease after chemotherapy failure.', 2),
('d6000000-0000-0000-0000-000000000025', 'C', 'Palliative chemotherapy only, given the relapse', false, 'Ruled out because relapsed Hodgkin lymphoma remains potentially curable with salvage therapy and transplant, so curative intent should be pursued in a fit patient.', 3),
('d6000000-0000-0000-0000-000000000025', 'D', 'Salvage chemotherapy (e.g., a brentuximab vedotin-containing or platinum-based regimen) followed by autologous stem cell transplantation if chemosensitive', true, 'Correct. Relapsed classical Hodgkin lymphoma after first-line ABVD is managed with salvage chemotherapy, increasingly incorporating brentuximab vedotin, followed by high-dose therapy and autologous transplant in chemosensitive, transplant-eligible patients.', 4),
('d6000000-0000-0000-0000-000000000025', 'E', 'Allogeneic stem cell transplant as first salvage option', false, 'Ruled out because autologous transplant with salvage chemotherapy is the standard first salvage approach; allogeneic transplant is generally reserved for relapse after autologous transplant.', 5),
('d6000000-0000-0000-0000-000000000026', 'A', 'Broad-spectrum antibiotics alone, presuming bacterial sepsis, without considering CRS', false, 'Ruled out because although infection should be covered empirically, the temporal relationship to CAR-T infusion and clinical picture are classic for cytokine release syndrome, requiring tocilizumab as first-line targeted treatment.', 1),
('d6000000-0000-0000-0000-000000000026', 'B', 'No specific intervention, as fevers post CAR-T are expected and self-limiting', false, 'Ruled out because hypotension and hypoxia indicate a higher-grade CRS requiring active intervention, not passive monitoring.', 2),
('d6000000-0000-0000-0000-000000000026', 'C', 'Tocilizumab, with corticosteroids added if refractory or severe', true, 'Correct. Cytokine release syndrome typically occurs in the days following CAR-T infusion; tocilizumab, an IL-6 receptor antagonist, is first-line treatment for CRS with haemodynamic or respiratory compromise, with corticosteroids added for severe or refractory cases.', 3),
('d6000000-0000-0000-0000-000000000026', 'D', 'High-dose corticosteroids alone as first-line, reserving tocilizumab for steroid failure', false, 'Ruled out because tocilizumab is generally used first-line for CRS with hypotension, with corticosteroids reserved for more severe or refractory cases or neurotoxicity.', 4),
('d6000000-0000-0000-0000-000000000026', 'E', 'Urgent plasma exchange', false, 'Ruled out because plasma exchange has no established role in cytokine release syndrome management.', 5),
('d6000000-0000-0000-0000-000000000027', 'A', 'Allopurinol alone, without rasburicase', false, 'Ruled out because in high-risk TLS, rasburicase is more effective and rapidly reduces existing urate levels, whereas allopurinol only prevents further urate formation.', 1),
('d6000000-0000-0000-0000-000000000027', 'B', 'Delay chemotherapy for 2 weeks to allow spontaneous urate normalisation', false, 'Ruled out because delaying definitive treatment of a rapidly proliferating, chemosensitive lymphoma is inappropriate and dangerous.', 2),
('d6000000-0000-0000-0000-000000000027', 'C', 'Restrict fluids to avoid tumour lysis-related fluid overload', false, 'Ruled out because aggressive hydration, not restriction, is a cornerstone of TLS prevention to maintain renal perfusion and urate excretion.', 3),
('d6000000-0000-0000-0000-000000000027', 'D', 'Give prophylactic potassium supplementation', false, 'Ruled out because hyperkalaemia, not hypokalaemia, is a feature of tumour lysis syndrome; potassium should be monitored and restricted, not supplemented.', 4),
('d6000000-0000-0000-0000-000000000027', 'E', 'Aggressive IV hydration and rasburicase prior to chemotherapy', true, 'Correct. Burkitt lymphoma is very high risk for tumour lysis syndrome; high-risk patients should receive aggressive IV hydration and rasburicase, which rapidly degrades existing uric acid, before and during initial chemotherapy.', 5),
('d6000000-0000-0000-0000-000000000028', 'A', 'Rituximab alone without a TKI', false, 'Ruled out because rituximab may be added in CD20-positive B-ALL but does not address the driving BCR-ABL1 fusion, for which a TKI is essential.', 1),
('d6000000-0000-0000-0000-000000000028', 'B', 'All-trans retinoic acid', false, 'Ruled out because ATRA is specific to APL and irrelevant to Ph+ ALL.', 2),
('d6000000-0000-0000-0000-000000000028', 'C', 'Standard chemotherapy alone without any targeted agent', false, 'Ruled out because Ph+ ALL historically had poor outcomes with chemotherapy alone; addition of a TKI is now essential.', 3),
('d6000000-0000-0000-0000-000000000028', 'D', 'A BCR-ABL1 tyrosine kinase inhibitor (e.g., dasatinib or imatinib), combined with chemotherapy and consideration of allogeneic transplant in remission', true, 'Correct. Ph+ ALL historically carried a poor prognosis with chemotherapy alone; addition of a TKI to chemotherapy has dramatically improved remission rates and survival and is now standard of care.', 4),
('d6000000-0000-0000-0000-000000000028', 'E', 'Hydroxycarbamide', false, 'Ruled out because hydroxycarbamide is used for cytoreduction in myeloproliferative disorders/hyperleukocytosis, not as targeted therapy for Ph+ ALL.', 5),
('d6000000-0000-0000-0000-000000000029', 'A', 'Aggressive IV hydration and treatment of hypercalcaemia, using a bisphosphonate with caution/dose adjustment for renal function or denosumab, alongside starting a daratumumab-based salvage regimen', true, 'Correct. Myeloma-related hypercalcaemia and renal impairment require prompt supportive management alongside rapid initiation of effective anti-myeloma therapy such as a daratumumab-based regimen to reverse the underlying process.', 1),
('d6000000-0000-0000-0000-000000000029', 'B', 'Start intravenous bisphosphonate at full standard dose without regard to renal function', false, 'Ruled out because bisphosphonates, particularly zoledronic acid, require dose adjustment or avoidance in significant renal impairment due to nephrotoxicity risk; denosumab is not renally cleared and may be preferred.', 2),
('d6000000-0000-0000-0000-000000000029', 'C', 'Delay any myeloma-specific treatment until renal function has fully normalised', false, 'Ruled out because myeloma-related renal impairment often requires prompt disease-directed treatment to reverse renal injury; delay may worsen prognosis.', 3),
('d6000000-0000-0000-0000-000000000029', 'D', 'Proceed straight to autologous stem cell transplant', false, 'Ruled out because this is not the immediate step in relapsed disease with hypercalcaemia and renal impairment requiring stabilisation and reinduction first.', 4),
('d6000000-0000-0000-0000-000000000029', 'E', 'Start high-dose dexamethasone alone without further anti-myeloma or supportive therapy', false, 'Ruled out because dexamethasone alone is insufficient for acute hypercalcaemia and progressive myeloma requiring a targeted salvage regimen and specific hypercalcaemia management.', 5),
('d6000000-0000-0000-0000-000000000030', 'A', 'Fludarabine, cyclophosphamide, rituximab (FCR) chemoimmunotherapy', false, 'Ruled out because del(17p)/TP53-mutated CLL responds poorly to chemoimmunotherapy with a high relapse rate; targeted agents are preferred.', 1),
('d6000000-0000-0000-0000-000000000030', 'B', 'A targeted regimen such as venetoclax plus obinutuzumab, or a BTK inhibitor such as ibrutinib/acalabrutinib, avoiding chemoimmunotherapy', true, 'Correct. CLL with del(17p)/TP53 mutation responds poorly to chemoimmunotherapy, as the DNA-damage response pathway required for chemotherapy-induced apoptosis is disrupted; targeted agents are preferred first-line regardless of fitness.', 2),
('d6000000-0000-0000-0000-000000000030', 'C', 'Watch and wait despite symptomatic progression', false, 'Ruled out because the patient has symptomatic disease requiring active treatment, not observation.', 3),
('d6000000-0000-0000-0000-000000000030', 'D', 'Bendamustine-rituximab', false, 'Ruled out because this is also a chemoimmunotherapy-based regimen, similarly ineffective in TP53-disrupted CLL.', 4),
('d6000000-0000-0000-0000-000000000030', 'E', 'Allogeneic stem cell transplant as first-line therapy', false, 'Ruled out because transplant is reserved for relapsed/refractory high-risk disease after failure of targeted agents, not first-line for newly symptomatic CLL.', 5),
('d6000000-0000-0000-0000-000000000031', 'A', 'Continue venesection and aspirin alone, as this is sufficient for all PV patients', false, 'Ruled out because high-risk features (age, prior thrombosis) mandate additional cytoreductive therapy beyond venesection and aspirin.', 1),
('d6000000-0000-0000-0000-000000000031', 'B', 'Start cytoreductive therapy (e.g., hydroxycarbamide) given his age over 60 and history of thrombosis', true, 'Correct. Age over 60 years and/or history of thrombosis define high-risk PV, mandating cytoreductive therapy in addition to venesection and aspirin.', 2),
('d6000000-0000-0000-0000-000000000031', 'C', 'Stop aspirin, as venesection alone is an adequate antithrombotic strategy', false, 'Ruled out because aspirin remains recommended in PV to reduce thrombotic risk in the absence of contraindication.', 3),
('d6000000-0000-0000-0000-000000000031', 'D', 'Proceed to allogeneic stem cell transplant', false, 'Ruled out because transplant is not indicated in chronic-phase PV and is reserved for progression to myelofibrosis or leukaemic transformation.', 4),
('d6000000-0000-0000-0000-000000000031', 'E', 'Start therapeutic anticoagulation instead of venesection', false, 'Ruled out because venesection to maintain haematocrit below 0.45, plus antiplatelet and cytoreductive therapy, is standard, not anticoagulation without a separate indication.', 5),
('d6000000-0000-0000-0000-000000000032', 'A', 'Continue hydroxycarbamide throughout pregnancy as it is safe', false, 'Ruled out because hydroxycarbamide is teratogenic and contraindicated in pregnancy.', 1),
('d6000000-0000-0000-0000-000000000032', 'B', 'Switch to anagrelide for cytoreduction during pregnancy', false, 'Ruled out because anagrelide is also generally avoided in pregnancy due to limited safety data; interferon-alpha is preferred if cytoreduction is required.', 2),
('d6000000-0000-0000-0000-000000000032', 'C', 'Stop all treatment including aspirin', false, 'Ruled out because low-dose aspirin is generally continued in ET during pregnancy to reduce the risk of placental vascular complications.', 3),
('d6000000-0000-0000-0000-000000000032', 'D', 'Proceed to urgent platelet apheresis as first step', false, 'Ruled out because apheresis is not first-line/routine management for chronic ET in pregnancy without an acute thrombotic emergency.', 4),
('d6000000-0000-0000-0000-000000000032', 'E', 'Stop hydroxycarbamide immediately as it is teratogenic, switch to low-dose aspirin, and consider interferon-alpha if cytoreduction is needed', true, 'Correct. Hydroxycarbamide is teratogenic and must be stopped when pregnancy is confirmed; interferon-alpha is the preferred cytoreductive agent in pregnancy as it does not cross the placenta in significant amounts, while low-dose aspirin is continued.', 5),
('d6000000-0000-0000-0000-000000000033', 'A', 'Start a JAK inhibitor (ruxolitinib)', true, 'Correct. Ruxolitinib is effective for reducing spleen size and improving constitutional symptoms in intermediate/high-risk myelofibrosis, and is preferred over hydroxycarbamide for these indications, including in patients not eligible for transplant.', 1),
('d6000000-0000-0000-0000-000000000033', 'B', 'Start hydroxycarbamide as first-line for splenomegaly control', false, 'Ruled out because ruxolitinib is more effective than hydroxycarbamide for spleen size reduction and constitutional symptom control in symptomatic higher-risk myelofibrosis.', 2),
('d6000000-0000-0000-0000-000000000033', 'C', 'Proceed to splenectomy as first-line management', false, 'Ruled out because splenectomy carries significant perioperative morbidity and mortality in myelofibrosis and is reserved for cases refractory to medical therapy.', 3),
('d6000000-0000-0000-0000-000000000033', 'D', 'Allogeneic stem cell transplant', false, 'Ruled out because he is not a transplant candidate due to comorbidities.', 4),
('d6000000-0000-0000-0000-000000000033', 'E', 'Observation alone given his transplant ineligibility', false, 'Ruled out because ruxolitinib offers effective symptom and spleen size control even when transplant is not feasible; active treatment should be offered.', 5),
('d6000000-0000-0000-0000-000000000034', 'A', 'This represents simple under-treated PV; increase venesection frequency', false, 'Ruled out because the picture of anaemia, worsening splenomegaly, a leucoerythroblastic film and marrow fibrosis indicates transformation to myelofibrosis, not ongoing erythrocytosis requiring venesection.', 1),
('d6000000-0000-0000-0000-000000000034', 'B', 'This represents transformation to acute myeloid leukaemia; start intensive induction chemotherapy', false, 'Ruled out because no evidence of blast transformation is given; this describes fibrotic transformation (post-PV myelofibrosis), not acute leukaemic transformation.', 2),
('d6000000-0000-0000-0000-000000000034', 'C', 'Post-polycythaemia vera myelofibrosis has developed; management should follow myelofibrosis-directed pathways (e.g., JAK inhibitor for symptomatic splenomegaly, transplant evaluation if eligible) rather than continued PV-specific therapy', true, 'Correct. PV can transform over time into post-PV myelofibrosis, characterised by anaemia, progressive splenomegaly, a leucoerythroblastic film and marrow fibrosis, requiring a shift from PV-specific therapy to myelofibrosis-directed management.', 3),
('d6000000-0000-0000-0000-000000000034', 'D', 'This is unrelated to her PV and represents a new, separate haematological diagnosis', false, 'Ruled out because this is a well-recognised natural evolution of PV, not an unrelated new disease.', 4),
('d6000000-0000-0000-0000-000000000034', 'E', 'No change in management is needed; continue current PV therapy unchanged', false, 'Ruled out because the change in disease biology requires a change in management approach.', 5),
('d6000000-0000-0000-0000-000000000035', 'A', 'CALR mutation status confers higher thrombosis risk than JAK2, so patient 2 should be treated more aggressively', false, 'Ruled out because evidence shows JAK2-mutated ET is associated with higher thrombotic risk compared with CALR-mutated ET, the opposite of this statement.', 1),
('d6000000-0000-0000-0000-000000000035', 'B', 'Mutation status has no bearing on thrombosis risk in ET; only platelet count matters', false, 'Ruled out because driver mutation status is now recognised as an important independent risk factor incorporated into modern risk stratification, not just platelet count or age.', 2),
('d6000000-0000-0000-0000-000000000035', 'C', 'Both patients require identical treatment regardless of mutation', false, 'Ruled out because mutation status contributes to individualised risk assessment and treatment decisions.', 3),
('d6000000-0000-0000-0000-000000000035', 'D', 'JAK2-mutated ET carries a higher thrombosis risk than CALR-mutated ET at a similar age, which may influence the threshold for starting cytoreductive and antiplatelet therapy', true, 'Correct. Revised risk stratification models such as IPSET-thrombosis incorporate driver mutation status, recognising that JAK2 V617F-mutated ET carries a higher thrombotic risk than CALR-mutated disease.', 4),
('d6000000-0000-0000-0000-000000000035', 'E', 'Only patients with platelet counts above 1000 x10^9/L require any antithrombotic consideration', false, 'Ruled out because extreme thrombocytosis is not the primary driver of thrombosis risk in ET; very high platelet counts can paradoxically be associated with acquired von Willebrand syndrome and bleeding risk instead.', 5),
('d6000000-0000-0000-0000-000000000036', 'A', 'Anticoagulation alone without addressing the underlying JAK2-positive clone', false, 'Ruled out because treating only the thrombosis without addressing the underlying MPN driving the prothrombotic state leaves ongoing risk of further thrombosis.', 1),
('d6000000-0000-0000-0000-000000000036', 'B', 'Cytoreductive therapy alone without anticoagulation', false, 'Ruled out because established venous thrombosis requires anticoagulation as well as addressing the underlying disorder.', 2),
('d6000000-0000-0000-0000-000000000036', 'C', 'Immediate liver transplantation as first-line management', false, 'Ruled out because transplant is reserved for fulminant or refractory liver failure, not the initial approach when the disease may respond to anticoagulation and cytoreduction.', 3),
('d6000000-0000-0000-0000-000000000036', 'D', 'No treatment needed as blood counts are only mildly abnormal', false, 'Ruled out because even occult MPN, with counts masked by splenomegaly/portal hypertension, requires treatment when a positive JAK2 mutation and unusual-site thrombosis are present.', 4),
('d6000000-0000-0000-0000-000000000036', 'E', 'Therapeutic anticoagulation, alongside cytoreductive therapy directed at the underlying occult myeloproliferative neoplasm, with hepatology input for the Budd-Chiari syndrome', true, 'Correct. Budd-Chiari syndrome and other unusual-site thromboses are strongly associated with underlying MPNs; management requires both anticoagulation for the thrombosis and cytoreductive therapy targeting the underlying MPN.', 5),
('d6000000-0000-0000-0000-000000000037', 'A', 'This is simply accelerated phase CML requiring only a TKI dose increase', false, 'Ruled out because a blast count of this magnitude defines blast crisis, a distinct and more aggressive phase requiring combination induction therapy, not dose adjustment alone.', 1),
('d6000000-0000-0000-0000-000000000037', 'B', 'Continue imatinib unchanged and monitor response over the next 3 months', false, 'Ruled out because blast crisis is a rapidly progressive phase if untreated, warranting immediate escalation of therapy.', 2),
('d6000000-0000-0000-0000-000000000037', 'C', 'This represents transformation to blast crisis; management requires blast-lineage-directed induction therapy combined with a potent TKI, with allogeneic transplant considered in eligible patients achieving a response', true, 'Correct. A blast percentage meeting WHO criteria for blast crisis represents transformation to an acute leukaemia-like phase requiring lineage-directed induction chemotherapy combined with a potent TKI.', 3),
('d6000000-0000-0000-0000-000000000037', 'D', 'Switch to a different second-generation TKI alone, without additional chemotherapy', false, 'Ruled out because TKI switch alone is inadequate for blast crisis; combination with lineage-appropriate induction chemotherapy is needed.', 4),
('d6000000-0000-0000-0000-000000000037', 'E', 'Refer for palliative care only, as this represents terminal disease', false, 'Ruled out because although prognosis is poorer than chronic phase, active combination therapy can achieve remission and should be pursued in eligible patients.', 5),
('d6000000-0000-0000-0000-000000000038', 'A', 'This represents unrelated new sepsis; treat with antibiotics alone and do not restart ruxolitinib', false, 'Ruled out because while infection should be excluded or covered, the clear temporal relationship to abrupt discontinuation is characteristic of withdrawal syndrome, and prompt reinstitution is key.', 1),
('d6000000-0000-0000-0000-000000000038', 'B', 'Ruxolitinib withdrawal (cytokine rebound) syndrome; management involves prompt reinstitution of ruxolitinib, or corticosteroids if reintroduction is delayed, alongside supportive care', true, 'Correct. Abrupt discontinuation of ruxolitinib can precipitate a severe cytokine rebound syndrome; prompt reinstitution of ruxolitinib is the key management step alongside supportive care.', 2),
('d6000000-0000-0000-0000-000000000038', 'C', 'This represents progression to blast phase myelofibrosis; start induction chemotherapy', false, 'Ruled out because the acute presentation temporally linked to abrupt drug cessation is most consistent with withdrawal syndrome rather than leukaemic transformation.', 3),
('d6000000-0000-0000-0000-000000000038', 'D', 'No specific management is needed; symptoms will resolve without intervention', false, 'Ruled out because this can be a severe, life-threatening syndrome requiring active management.', 4),
('d6000000-0000-0000-0000-000000000038', 'E', 'Start a higher dose of a different, previously untried JAK inhibitor', false, 'Ruled out because the priority is prompt reinstitution of ruxolitinib, not initiating a novel untried agent for the first time in an acutely unwell patient.', 5),
('d6000000-0000-0000-0000-000000000039', 'A', 'Imatinib', false, 'Ruled out because imatinib is ineffective against the KIT D816V mutation, which confers imatinib resistance, unlike non-D816V KIT mutations which may respond.', 1),
('d6000000-0000-0000-0000-000000000039', 'B', 'Rituximab', false, 'Ruled out because rituximab targets CD20 on B-cells and is not relevant to mast cell disease.', 2),
('d6000000-0000-0000-0000-000000000039', 'C', 'All-trans retinoic acid', false, 'Ruled out because ATRA is specific to APL and not relevant to mastocytosis.', 3),
('d6000000-0000-0000-0000-000000000039', 'D', 'Midostaurin, a multi-kinase inhibitor with activity against mutant KIT', true, 'Correct. Advanced systemic mastocytosis with the KIT D816V mutation is resistant to imatinib; midostaurin (and newer avapritinib) have activity against KIT D816V and are used in advanced/aggressive disease with organ dysfunction.', 4),
('d6000000-0000-0000-0000-000000000039', 'E', 'Standard antihistamines alone as definitive treatment', false, 'Ruled out because antihistamines help symptomatic control of mediator release but do not address the underlying advanced clonal mast cell disease with organ damage, which requires targeted therapy.', 5),
('d6000000-0000-0000-0000-000000000040', 'A', 'Switch to ruxolitinib as second-line cytoreductive therapy', true, 'Correct. Ruxolitinib is licensed as second-line therapy for PV in patients resistant to or intolerant of hydroxycarbamide, providing effective haematocrit control and improvement of associated symptoms.', 1),
('d6000000-0000-0000-0000-000000000040', 'B', 'Continue hydroxycarbamide at a higher dose despite the leg ulcers', false, 'Ruled out because hydroxycarbamide-induced leg ulcers are an indication to switch therapy, not increase the dose, which would worsen skin toxicity.', 2),
('d6000000-0000-0000-0000-000000000040', 'C', 'Switch to busulfan as second-line agent', false, 'Ruled out because busulfan is an older alkylating agent with leukaemogenic potential, no longer preferred as standard second-line therapy given the availability of ruxolitinib.', 3),
('d6000000-0000-0000-0000-000000000040', 'D', 'Stop all cytoreductive therapy and rely on venesection alone', false, 'Ruled out because he has high-risk disease with resistance/intolerance to first-line therapy, still requiring cytoreductive control.', 4),
('d6000000-0000-0000-0000-000000000040', 'E', 'Switch to low-dose aspirin alone, discontinuing cytoreductive therapy', false, 'Ruled out because aspirin alone is inadequate cytoreductive control for high-risk, resistant/intolerant PV.', 5),
('d6000000-0000-0000-0000-000000000041', 'A', 'Transfusion-associated circulatory overload (TACO); stop the transfusion, give oxygen and IV diuretics, and consider slower rates or diuretic cover for future transfusions', true, 'Correct. TACO typically presents with hypertension, acute pulmonary oedema, and a raised BNP relative to baseline, especially in patients with pre-existing cardiac dysfunction; management involves stopping the transfusion, diuresis, and oxygen.', 1),
('d6000000-0000-0000-0000-000000000041', 'B', 'Transfusion-related acute lung injury (TRALI); manage with supportive respiratory care alone', false, 'Ruled out because TRALI classically causes hypotension, not hypertension, with acute non-cardiogenic pulmonary oedema and no significant BNP rise, unlike this presentation.', 2),
('d6000000-0000-0000-0000-000000000041', 'C', 'Anaphylactic transfusion reaction; give IM adrenaline', false, 'Ruled out because there is no urticaria, angioedema, or bronchospasm described; the clinical and biochemical picture instead fits fluid overload.', 3),
('d6000000-0000-0000-0000-000000000041', 'D', 'Acute haemolytic transfusion reaction; stop the transfusion and send a direct antiglobulin test and repeat crossmatch', false, 'Ruled out because there is no fever, back pain, haemoglobinuria, or haemolysis markers described; the picture is respiratory/cardiovascular overload.', 4),
('d6000000-0000-0000-0000-000000000041', 'E', 'Bacterial contamination of the blood product; start broad-spectrum antibiotics', false, 'Ruled out because there is no fever or rigors or septic picture described; hypertension and pulmonary oedema in a patient with pre-existing heart failure strongly favour volume overload.', 5),
('d6000000-0000-0000-0000-000000000042', 'A', 'Transfuse red cells alone initially, withholding FFP and platelets until formal coagulation results return', false, 'Ruled out because waiting for lab results in massive haemorrhage delays correction of trauma-induced coagulopathy; empirical balanced ratio transfusion is started immediately.', 1),
('d6000000-0000-0000-0000-000000000042', 'B', 'Give crystalloid resuscitation to a normal blood pressure target before any blood products', false, 'Ruled out because large-volume crystalloid resuscitation worsens dilutional coagulopathy and is avoided in favour of early balanced blood product transfusion and permissive hypotension until haemorrhage control.', 2),
('d6000000-0000-0000-0000-000000000042', 'C', 'Transfuse red cells, fresh frozen plasma, and platelets in a fixed ratio approximating 1:1:1, alongside early tranexamic acid', true, 'Correct. Massive transfusion protocols use a balanced ratio of red cells, FFP, and platelets to replicate whole blood and reduce dilutional coagulopathy, and early tranexamic acid reduces mortality in trauma haemorrhage.', 3),
('d6000000-0000-0000-0000-000000000042', 'D', 'Withhold tranexamic acid due to theoretical thrombotic risk', false, 'Ruled out because early tranexamic acid, given within 3 hours of injury, reduces mortality in trauma haemorrhage and should not be withheld.', 4),
('d6000000-0000-0000-0000-000000000042', 'E', 'Use cryoprecipitate as the primary resuscitation fluid before red cells', false, 'Ruled out because red cells with FFP and platelets in balanced ratio are the primary resuscitation products; cryoprecipitate is added specifically to correct low fibrinogen, not as the primary resuscitation fluid.', 5),
('d6000000-0000-0000-0000-000000000043', 'A', 'Slow the transfusion rate and continue, monitoring symptoms', false, 'Ruled out because suspected acute haemolytic transfusion reaction requires immediate cessation, not simply slowing the rate.', 1),
('d6000000-0000-0000-0000-000000000043', 'B', 'Give IV furosemide and continue the transfusion', false, 'Ruled out because continuing the transfusion with ongoing incompatible red cell destruction is dangerous; the priority is stopping the transfusion first.', 2),
('d6000000-0000-0000-0000-000000000043', 'C', 'Administer IM adrenaline as first step', false, 'Ruled out because adrenaline is used for anaphylaxis, not the primary treatment for a haemolytic transfusion reaction, and this presentation with loin pain and dark urine fits acute haemolysis rather than anaphylaxis.', 3),
('d6000000-0000-0000-0000-000000000043', 'D', 'Restart the same unit after a short pause once symptoms improve slightly', false, 'Ruled out because once an acute haemolytic reaction is suspected, that unit must not be re-administered; further investigation is mandatory before any further transfusion.', 4),
('d6000000-0000-0000-0000-000000000043', 'E', 'Stop the transfusion immediately, maintain IV access with saline, send blood for repeat group and crossmatch/direct antiglobulin test, and monitor renal function and urine output closely', true, 'Correct. Acute haemolytic transfusion reactions constitute a medical emergency requiring immediate cessation of the transfusion, supportive fluids to protect renal perfusion, and urgent investigation.', 5),
('d6000000-0000-0000-0000-000000000044', 'A', 'Acute haemolytic transfusion reaction due to ABO incompatibility', false, 'Ruled out because acute haemolytic reactions occur within minutes to hours, not a week later, and typically involve ABO antibodies, not a newly detected minor alloantibody.', 1),
('d6000000-0000-0000-0000-000000000044', 'B', 'Delayed haemolytic transfusion reaction due to an anamnestic response to a previously sensitised red cell antigen, with antibody levels too low to detect at the time of crossmatch', true, 'Correct. Delayed haemolytic transfusion reactions occur days to weeks after transfusion in previously alloimmunised patients whose antibody titres had fallen below detectable levels, rising rapidly on re-exposure.', 2),
('d6000000-0000-0000-0000-000000000044', 'C', 'Transfusion-related acute lung injury', false, 'Ruled out because TRALI presents as acute respiratory distress within 6 hours of transfusion, not jaundice and anaemia at 7 days.', 3),
('d6000000-0000-0000-0000-000000000044', 'D', 'Transfusion-associated graft-versus-host disease', false, 'Ruled out because TA-GVHD typically presents 1-6 weeks post-transfusion with fever, rash, diarrhoea, and pancytopenia/marrow aplasia, not isolated haemolysis with a new alloantibody.', 4),
('d6000000-0000-0000-0000-000000000044', 'E', 'Simple recurrence of her underlying chronic anaemia unrelated to transfusion', false, 'Ruled out because the timing, positive DAT, and newly detectable alloantibody strongly point to a delayed haemolytic transfusion reaction rather than coincidental unrelated anaemia.', 5),
('d6000000-0000-0000-0000-000000000045', 'A', 'Immediately dismiss the concern as a normal reaction and continue at the same rate without further assessment', false, 'Ruled out because febrile reactions still require assessment to exclude bacterial contamination or an early haemolytic/septic reaction before assuming a benign cause.', 1),
('d6000000-0000-0000-0000-000000000045', 'B', 'Automatically diagnose bacterial contamination and start broad-spectrum antibiotics without further clinical assessment', false, 'Ruled out because most isolated fever/mild rigor reactions with stable observations are benign FNHTR, though bacterial contamination should be considered with additional features such as hypotension or high fever.', 2),
('d6000000-0000-0000-0000-000000000045', 'C', 'Administer IM adrenaline', false, 'Ruled out because there are no features of anaphylaxis such as urticaria, angioedema, or bronchospasm present.', 3),
('d6000000-0000-0000-0000-000000000045', 'D', 'Stop or pause the transfusion, assess clinically to exclude a more serious reaction, give antipyretics, and if the picture is reassuring consider cautious resumption at a slower rate with close monitoring', true, 'Correct. Febrile reactions require clinical assessment to exclude bacterial contamination or an early haemolytic/septic reaction before managing as a benign febrile non-haemolytic transfusion reaction with antipyretics and rate reduction.', 4),
('d6000000-0000-0000-0000-000000000045', 'E', 'Increase the transfusion rate to complete it quickly before further reaction develops', false, 'Ruled out because increasing the rate during a reaction is inappropriate; the transfusion should be paused and reassessed first.', 5),
('d6000000-0000-0000-0000-000000000046', 'A', 'CMV-negative components only, without irradiation', false, 'Ruled out because the specific risk here, purine analogue chemotherapy and Hodgkin lymphoma, is transfusion-associated GVHD, which requires irradiation specifically, not CMV-negative status alone.', 1),
('d6000000-0000-0000-0000-000000000046', 'B', 'Washed red cells only', false, 'Ruled out because washed components remove plasma proteins for patients with severe allergic reactions or IgA deficiency, not to prevent TA-GVHD.', 2),
('d6000000-0000-0000-0000-000000000046', 'C', 'No special modification is required for this patient', false, 'Ruled out because purine analogue-treated patients and Hodgkin lymphoma patients are at recognised high risk of TA-GVHD and require irradiated components.', 3),
('d6000000-0000-0000-0000-000000000046', 'D', 'Autologous blood donation only', false, 'Ruled out because this is not practical for acute anaemia and does not address the specific cellular immune risk requiring irradiation.', 4),
('d6000000-0000-0000-0000-000000000046', 'E', 'Irradiated blood components, to prevent transfusion-associated graft-versus-host disease', true, 'Correct. Purine analogue-treated patients and those with Hodgkin lymphoma are at recognised high risk of transfusion-associated GVHD, and irradiation inactivates donor lymphocytes to prevent this almost universally fatal complication.', 5),
('d6000000-0000-0000-0000-000000000047', 'A', 'The component should be CMV-seronegative (or leucodepleted), irradiated, fresh, and group O RhD-negative, Kell-negative, matched to avoid the relevant antigen', true, 'Correct. Intrauterine transfusion requires irradiated, CMV-safe, fresh red cell components due to the heightened risk of TA-GVHD and CMV transmission in the immunologically immature fetus, and must be matched to avoid the specific alloantigen implicated, here Kell.', 1),
('d6000000-0000-0000-0000-000000000047', 'B', 'Standard, non-irradiated, non-CMV-tested red cells are adequate, as for any adult transfusion', false, 'Ruled out because intrauterine transfusion recipients require irradiated, CMV-safe components due to their immature immune systems and specific vulnerability to TA-GVHD and CMV transmission.', 2),
('d6000000-0000-0000-0000-000000000047', 'C', 'Only ABO and RhD matching is required, without needing to avoid the Kell antigen specifically', false, 'Ruled out because given the anti-Kell alloimmunisation driving the fetal anaemia, Kell-negative units must be specifically selected in addition to routine ABO/RhD compatibility.', 3),
('d6000000-0000-0000-0000-000000000047', 'D', 'Irradiation is not necessary for intrauterine transfusion, only for postnatal exchange transfusion', false, 'Ruled out because irradiation is required for intrauterine transfusions given the significant TA-GVHD risk in the fetus/neonate.', 4),
('d6000000-0000-0000-0000-000000000047', 'E', 'Fresh frozen plasma should be used instead of red cells for this purpose', false, 'Ruled out because intrauterine transfusion for fetal anaemia uses red cells, not FFP.', 5),
('d6000000-0000-0000-0000-000000000048', 'A', 'No anti-D immunoglobulin is required as she is already receiving routine antenatal prophylaxis', false, 'Ruled out because a potentially sensitising event requires additional anti-D immunoglobulin administration separate from routine antenatal prophylactic dosing.', 1),
('d6000000-0000-0000-0000-000000000048', 'B', 'Anti-D immunoglobulin is unnecessary since fetal heart activity is confirmed and there is no abruption', false, 'Ruled out because the risk of fetomaternal haemorrhage and sensitisation exists regardless of reassuring current fetal wellbeing or scan findings after trauma.', 2),
('d6000000-0000-0000-0000-000000000048', 'C', 'Give anti-D immunoglobulin only if she becomes symptomatic with bleeding in the following days', false, 'Ruled out because prophylaxis should be given promptly after the sensitising event itself, ideally within 72 hours, not deferred pending symptoms.', 3),
('d6000000-0000-0000-0000-000000000048', 'D', 'Perform a Kleihauer test to estimate the volume of fetomaternal haemorrhage and give anti-D immunoglobulin, with the dose adjusted according to the result, as soon as possible after the sensitising event', true, 'Correct. A potentially sensitising event such as abdominal trauma warrants additional anti-D immunoglobulin, separate from routine antenatal prophylactic dosing, guided by a Kleihauer test to quantify fetomaternal haemorrhage.', 4),
('d6000000-0000-0000-0000-000000000048', 'E', $x$Test the father's Rhesus status before deciding whether to give anti-D immunoglobulin$x$, false, 'Ruled out because paternal testing does not need to precede prompt anti-D administration in an urgent sensitising event scenario.', 5),
('d6000000-0000-0000-0000-000000000049', 'A', 'This is expected in AML and no further investigation or change in platelet product is needed', false, 'Ruled out because persistently poor increments without an obvious non-immune consumptive cause should prompt investigation for HLA alloimmunisation, not be dismissed.', 1),
('d6000000-0000-0000-0000-000000000049', 'B', 'Switch to more frequent standard random-donor platelet transfusions at higher doses', false, 'Ruled out because simply increasing the dose or frequency of standard, non-HLA-matched units is ineffective if the cause is HLA alloantibody-mediated destruction.', 2),
('d6000000-0000-0000-0000-000000000049', 'C', 'Immune platelet transfusion refractoriness, likely due to HLA alloimmunisation; test for HLA (and platelet-specific) antibodies and consider HLA-matched or crossmatch-compatible platelet units', true, 'Correct. Persistently poor increments without an obvious non-immune consumptive cause should prompt investigation for HLA alloimmunisation, and HLA-matched or crossmatch-compatible units can overcome immune refractoriness.', 3),
('d6000000-0000-0000-0000-000000000049', 'D', 'This indicates DIC and she should be started on heparin', false, 'Ruled out because there are no supportive findings for DIC, and heparin is not an appropriate blind response to refractoriness.', 4),
('d6000000-0000-0000-0000-000000000049', 'E', 'Splenectomy should be performed to improve platelet increments', false, 'Ruled out because there is no splenomegaly described, and splenectomy is not an appropriate step in refractoriness without confirmed hypersplenism as the cause.', 5),
('d6000000-0000-0000-0000-000000000050', 'A', 'Simple delayed haemolytic transfusion reaction from a newly formed alloantibody; give further transfusion to correct the haemoglobin', false, 'Ruled out because hyperhaemolysis destroys transfused and native red cells often without a detectable new alloantibody, and further transfusion can paradoxically worsen haemolysis, unlike a typical delayed haemolytic reaction.', 1),
('d6000000-0000-0000-0000-000000000050', 'B', 'Hyperhaemolysis syndrome; further red cell transfusion should generally be avoided, as it may worsen haemolysis, and treatment should focus on immunosuppression such as IV corticosteroids and/or IVIG with haematology input', true, 'Correct. Hyperhaemolysis syndrome destroys both transfused and native red cells, often without a detectable new alloantibody, and further transfusion can paradoxically worsen haemolysis; management centres on immunosuppression.', 2),
('d6000000-0000-0000-0000-000000000050', 'C', 'This represents an acute vaso-occlusive crisis alone unrelated to the transfusion; continue simple supportive management', false, 'Ruled out because the marked drop below pre-transfusion baseline haemoglobin with haemolysis markers, especially with a similar prior history, indicates hyperhaemolysis syndrome, a specific transfusion complication.', 3),
('d6000000-0000-0000-0000-000000000050', 'D', 'Start hydroxyurea urgently to manage this acute presentation', false, 'Ruled out because hydroxyurea is a chronic disease-modifying agent with no role in the acute management of hyperhaemolysis syndrome.', 4),
('d6000000-0000-0000-0000-000000000050', 'E', 'Perform urgent splenectomy', false, 'Ruled out because splenectomy is not a recognised treatment for acute hyperhaemolysis syndrome; management centres on immunosuppression and avoiding further transfusion where possible.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d6000000-0000-0000-0000-000000000001', 'IV iron is preferred over oral iron in IBD patients with intolerance, malabsorption, or ongoing inflammation impairing enteral iron absorption via hepcidin-mediated blockade.', 1),
('d6000000-0000-0000-0000-000000000001', 'Oral iron is frequently poorly tolerated in active or previously resected IBD and can exacerbate GI symptoms; IV formulations bypass absorption issues.', 2),
('d6000000-0000-0000-0000-000000000001', 'Blood transfusion should be reserved for symptomatic anaemia or haemodynamic instability, not for correctable iron deficiency anaemia amenable to iron replacement.', 3),
('d6000000-0000-0000-0000-000000000002', 'Rituximab is favoured as second-line therapy for steroid-refractory or steroid-dependent warm AIHA due to good response rates and a favourable toxicity profile compared with splenectomy.', 1),
('d6000000-0000-0000-0000-000000000002', 'Splenectomy remains an option for rituximab failure or when rapid, durable remission is required and rituximab is contraindicated or unavailable.', 2),
('d6000000-0000-0000-0000-000000000002', 'CLL-associated AIHA reflects immune dysregulation from the underlying lymphoproliferative disorder and treatment of the CLL itself may be needed if AIHA remains refractory.', 3),
('d6000000-0000-0000-0000-000000000003', 'Folic acid must never be given before correcting B12 deficiency, as it can accelerate the neurological manifestations of B12 deficiency (subacute combined degeneration) without correcting the underlying defect.', 1),
('d6000000-0000-0000-0000-000000000003', 'Neurological involvement in B12 deficiency mandates prompt parenteral (IM) hydroxocobalamin replacement rather than oral therapy as first-line treatment.', 2),
('d6000000-0000-0000-0000-000000000003', 'Pernicious anaemia (intrinsic factor antibody positive) is an autoimmune cause of B12 deficiency requiring lifelong replacement therapy.', 3),
('d6000000-0000-0000-0000-000000000004', 'In CKD, ferritin behaves as an acute-phase reactant and can be elevated despite true or functional iron deficiency; transferrin saturation below 20% with ESA hyporesponsiveness supports iron therapy even with a high ferritin.', 1),
('d6000000-0000-0000-0000-000000000004', 'IV iron is preferred in dialysis patients due to poor gut absorption and ongoing systemic inflammation.', 2),
('d6000000-0000-0000-0000-000000000004', 'Red cell transfusion in potential transplant candidates should be minimised because of the risk of alloimmunisation affecting future transplant compatibility.', 3),
('d6000000-0000-0000-0000-000000000005', 'Exchange transfusion is preferred over simple transfusion in severe or progressive acute chest syndrome as it reduces HbS percentage more effectively without significantly raising overall viscosity.', 1),
('d6000000-0000-0000-0000-000000000005', 'Acute chest syndrome is a leading cause of death in sickle cell disease and requires aggressive multimodal management, escalating to transfusion when supportive measures fail.', 2),
('d6000000-0000-0000-0000-000000000005', 'Hydroxyurea reduces the long-term frequency of vaso-occlusive crises and acute chest syndrome episodes but has no acute treatment role.', 3),
('d6000000-0000-0000-0000-000000000006', 'Cardiac T2* MRI below 10 ms indicates severe myocardial iron loading and high risk of arrhythmia or heart failure, requiring intensified chelation even in asymptomatic patients, since cardiac iron deposition precedes symptomatic dysfunction.', 1),
('d6000000-0000-0000-0000-000000000006', 'Deferiprone has particular efficacy at removing cardiac iron compared with desferrioxamine or deferasirox monotherapy, making deferiprone-based regimens preferred when cardiac iron loading is significant.', 2),
('d6000000-0000-0000-0000-000000000006', 'Liver and cardiac iron loading can be discordant; cardiac T2* should independently guide chelation intensity regardless of liver iron concentration.', 3),
('d6000000-0000-0000-0000-000000000007', 'Complement (C5) inhibitors such as eculizumab markedly increase susceptibility to infections with encapsulated organisms, particularly Neisseria meningitidis; meningococcal vaccination and often antibiotic prophylaxis are mandatory before starting therapy.', 1),
('d6000000-0000-0000-0000-000000000007', 'PNH is characterised by complement-mediated intravascular haemolysis and a markedly increased risk of thrombosis, often at atypical sites such as hepatic or mesenteric veins, which is a major indication for complement inhibitor therapy.', 2),
('d6000000-0000-0000-0000-000000000007', 'PNH frequently arises in the context of, or alongside, aplastic anaemia due to clonal expansion of a GPI-anchor-deficient haematopoietic clone.', 3),
('d6000000-0000-0000-0000-000000000008', 'G6PD deficiency predisposes to oxidative haemolysis triggered by certain drugs (e.g., nitrofurantoin, sulfonamides, dapsone, primaquine), fava beans, or infection; the mainstay of management is prompt withdrawal of the trigger with supportive care.', 1),
('d6000000-0000-0000-0000-000000000008', 'Bite cells and Heinz bodies on blood film reflect oxidative damage to haemoglobin and red cell membranes characteristic of G6PD deficiency-related haemolysis.', 2),
('d6000000-0000-0000-0000-000000000008', 'Haemolysis is usually self-limiting once the trigger is removed, though severe cases may require transfusion and monitoring for acute kidney injury from haemoglobinuria.', 3),
('d6000000-0000-0000-0000-000000000009', 'In young patients with severe aplastic anaemia and an available HLA-matched sibling donor, upfront allogeneic stem cell transplantation is preferred over immunosuppressive therapy due to superior long-term survival and lower risk of clonal evolution to MDS/AML.', 1),
('d6000000-0000-0000-0000-000000000009', 'Immunosuppressive therapy (ATG plus ciclosporin, often with eltrombopag) is reserved for patients without a matched sibling donor or those unsuitable for transplant.', 2),
('d6000000-0000-0000-0000-000000000009', 'Untreated severe aplastic anaemia carries very high mortality from infection and bleeding, mandating urgent definitive therapy.', 3),
('d6000000-0000-0000-0000-000000000010', 'Luspatercept, an erythroid maturation agent, is approved for transfusion-dependent anaemia in lower-risk MDS with ring sideroblasts (SF3B1-mutated) after ESA failure or unsuitability.', 1),
('d6000000-0000-0000-0000-000000000010', 'A high baseline serum erythropoietin level predicts poor response to ESA therapy, guiding earlier consideration of alternative agents.', 2),
('d6000000-0000-0000-0000-000000000010', 'Allogeneic transplant and intensive chemotherapy are reserved for higher-risk MDS or transformation to AML, not lower-risk transfusion-dependent disease.', 3),
('d6000000-0000-0000-0000-000000000011', 'Emicizumab, a bispecific antibody mimicking factor VIII cofactor activity, is effective prophylaxis in haemophilia A patients with inhibitors, as it is not neutralised by anti-FVIII antibodies.', 1),
('d6000000-0000-0000-0000-000000000011', 'Immune tolerance induction (repeated high-dose factor VIII) aims to eradicate the inhibitor over months but does not provide immediate bleed protection.', 2),
('d6000000-0000-0000-0000-000000000011', 'Breakthrough bleeds in emicizumab-treated inhibitor patients are managed with bypassing agents, with caution regarding concomitant activated PCC due to thrombotic microangiopathy risk.', 3),
('d6000000-0000-0000-0000-000000000012', 'In type 2B VWD, the mutant VWF has increased affinity for platelet GPIb, so DDAVP-induced VWF release can cause platelet aggregation/clumping and paradoxically worsen thrombocytopenia; DDAVP is generally contraindicated.', 1),
('d6000000-0000-0000-0000-000000000012', 'Type 2B VWD is distinguished by enhanced ristocetin-induced platelet aggregation at low ristocetin concentrations and often baseline mild thrombocytopenia.', 2),
('d6000000-0000-0000-0000-000000000012', 'Perioperative management of type 2B VWD relies on VWF-containing factor concentrate rather than DDAVP.', 3),
('d6000000-0000-0000-0000-000000000013', 'Acquired haemophilia A results from autoantibodies against factor VIII, presenting with a mixing study that fails to correct (unlike a simple factor deficiency), and requires both bypassing agents for acute bleeding and immunosuppression for inhibitor eradication.', 1),
('d6000000-0000-0000-0000-000000000013', 'Bypassing agents (rFVIIa or aPCC) are used because factor VIII concentrate is neutralised by the circulating inhibitor and is ineffective at controlling bleeding.', 2),
('d6000000-0000-0000-0000-000000000013', 'Acquired haemophilia A can be associated with malignancy, autoimmune disease, pregnancy, or be idiopathic, particularly in older adults.', 3),
('d6000000-0000-0000-0000-000000000014', 'DIC management centres on treating the underlying trigger (here, sepsis) alongside targeted replacement of consumed clotting factors, fibrinogen (via cryoprecipitate or fibrinogen concentrate), and platelets guided by bleeding severity and laboratory trend.', 1),
('d6000000-0000-0000-0000-000000000014', 'Anticoagulation has a limited role in DIC and is generally reserved for cases with predominant thrombotic manifestations without significant bleeding.', 2),
('d6000000-0000-0000-0000-000000000014', 'Antifibrinolytics are generally avoided in DIC due to the risk of promoting pathological thrombosis, except in specific bleeding-predominant subtypes under specialist guidance.', 3),
('d6000000-0000-0000-0000-000000000015', 'Life-threatening warfarin-associated bleeding requires rapid reversal with 4-factor PCC combined with IV vitamin K to sustain reversal and prevent rebound coagulopathy.', 1),
('d6000000-0000-0000-0000-000000000015', 'FFP is inferior to PCC for emergency warfarin reversal due to slower preparation, larger required volume, and less complete/rapid factor correction.', 2),
('d6000000-0000-0000-0000-000000000015', 'Protamine and idarucizumab are specific reversal agents for heparin and dabigatran respectively, not warfarin.', 3),
('d6000000-0000-0000-0000-000000000016', 'Andexanet alfa is a specific reversal agent for factor Xa inhibitors (apixaban, rivaroxaban); where unavailable, 4-factor PCC is used as an alternative for major bleeding.', 1),
('d6000000-0000-0000-0000-000000000016', 'Idarucizumab specifically reverses dabigatran (a direct thrombin inhibitor) and has no effect on factor Xa inhibitors.', 2),
('d6000000-0000-0000-0000-000000000016', 'Reversal strategy depends on identifying the specific DOAC class (direct thrombin inhibitor vs factor Xa inhibitor), as reversal agents are not interchangeable.', 3),
('d6000000-0000-0000-0000-000000000017', 'Thrombopoietin receptor agonists (eltrombopag, romiplostim) are effective second-line options for chronic ITP refractory to or relapsing after corticosteroids, particularly when splenectomy is declined or deferred.', 1),
('d6000000-0000-0000-0000-000000000017', 'Splenectomy remains effective in refractory ITP but should not be pursued against patient preference; alternative medical therapies should be offered instead.', 2),
('d6000000-0000-0000-0000-000000000017', 'Rituximab is another second-line option in ITP; choice depends on patient factors, bleeding risk, and preference for a finite versus chronic treatment course.', 3),
('d6000000-0000-0000-0000-000000000018', 'TTP is a haematological emergency requiring urgent plasma exchange without waiting for confirmatory ADAMTS13 assay results when clinical suspicion (e.g., a high PLASMIC score) is strong.', 1),
('d6000000-0000-0000-0000-000000000018', 'Platelet transfusion is generally avoided in TTP outside life-threatening bleeding as it may fuel microvascular thrombosis and worsen organ ischaemia.', 2),
('d6000000-0000-0000-0000-000000000018', 'Caplacizumab (an anti-VWF nanobody) and immunosuppression (corticosteroids, rituximab) are increasingly used alongside plasma exchange to reduce time to platelet normalisation and prevent relapse.', 3),
('d6000000-0000-0000-0000-000000000019', 'HIT requires immediate cessation of all heparin products (including LMWH, due to cross-reactivity) and initiation of an alternative non-heparin anticoagulant such as argatroban, fondaparinux, or a DOAC once appropriate.', 1),
('d6000000-0000-0000-0000-000000000019', 'Warfarin should not be started until the platelet count has substantially recovered, as it can precipitate venous limb gangrene or skin necrosis due to acute protein C depletion in the pro-thrombotic HIT state.', 2),
('d6000000-0000-0000-0000-000000000019', 'HIT is a prothrombotic disorder despite thrombocytopenia; platelet transfusion is generally avoided as it may exacerbate thrombosis.', 3),
('d6000000-0000-0000-0000-000000000020', 'DOACs are not recommended for patients with triple-positive antiphospholipid syndrome and prior thrombosis, as trial evidence demonstrates higher rates of recurrent thrombotic events, particularly arterial, compared with vitamin K antagonist therapy.', 1),
('d6000000-0000-0000-0000-000000000020', 'Recurrent thrombosis despite standard-intensity warfarin in APS should prompt reassessment of adherence and consideration of a higher INR target rather than abandoning vitamin K antagonist therapy.', 2),
('d6000000-0000-0000-0000-000000000020', 'Triple positivity (lupus anticoagulant, anticardiolipin, and anti-beta2-glycoprotein I antibodies) confers the highest thrombotic risk phenotype in APS.', 3),
('d6000000-0000-0000-0000-000000000021', 'The T315I gatekeeper mutation confers resistance to imatinib and most second-generation TKIs (dasatinib, nilotinib, bosutinib); ponatinib and asciminib retain activity against this mutation.', 1),
('d6000000-0000-0000-0000-000000000021', 'Loss of major molecular response on TKI therapy should prompt BCR-ABL1 kinase domain mutation testing to guide subsequent TKI selection.', 2),
('d6000000-0000-0000-0000-000000000021', 'Allogeneic stem cell transplant remains an option for TKI-refractory CML, particularly with T315I in advanced phase disease or failure of available TKIs.', 3),
('d6000000-0000-0000-0000-000000000022', 'Differentiation syndrome, occurring with ATRA and/or arsenic trioxide in APL, presents with fever, dyspnoea, pulmonary infiltrates, weight gain and hypotension, and is treated promptly with high-dose corticosteroids.', 1),
('d6000000-0000-0000-0000-000000000022', 'APL carries a high risk of early bleeding/coagulopathy (DIC) at presentation, and leukapheresis is generally avoided due to the risk of precipitating or worsening bleeding.', 2),
('d6000000-0000-0000-0000-000000000022', 'Early recognition and steroid treatment of differentiation syndrome has substantially reduced its associated mortality in APL treatment.', 3),
('d6000000-0000-0000-0000-000000000023', 'Richter transformation refers to CLL evolving into an aggressive lymphoma (usually DLBCL, occasionally Hodgkin lymphoma), suggested by asymmetric rapid lymphadenopathy, systemic B symptoms, and markedly raised LDH, confirmed by biopsy.', 1),
('d6000000-0000-0000-0000-000000000023', 'Clonally related Richter transformation carries a worse prognosis than clonally unrelated transformation, and treatment follows aggressive lymphoma protocols with consideration of transplant consolidation in responders.', 2),
('d6000000-0000-0000-0000-000000000023', 'Rapid asymmetric nodal enlargement in a known CLL patient should prompt biopsy to exclude transformation rather than assuming simple disease progression.', 3),
('d6000000-0000-0000-0000-000000000024', 'FLT3-ITD mutations, particularly with a high allelic ratio, confer an adverse prognosis in AML; addition of midostaurin to induction and consolidation chemotherapy improves survival.', 1),
('d6000000-0000-0000-0000-000000000024', 'Gilteritinib, a more selective FLT3 inhibitor, is used in relapsed/refractory FLT3-mutated AML.', 2),
('d6000000-0000-0000-0000-000000000024', 'FLT3-mutated AML with a high allelic ratio is generally considered for allogeneic stem cell transplant in first remission given the adverse risk profile.', 3),
('d6000000-0000-0000-0000-000000000025', 'Relapsed classical Hodgkin lymphoma after first-line ABVD is managed with salvage chemotherapy, increasingly incorporating brentuximab vedotin, followed by high-dose therapy and autologous stem cell transplantation in chemosensitive, transplant-eligible patients.', 1),
('d6000000-0000-0000-0000-000000000025', 'Allogeneic transplant is generally reserved for relapse after autologous transplant failure, given greater toxicity but potential graft-versus-lymphoma effect.', 2),
('d6000000-0000-0000-0000-000000000025', 'Early relapse (within 12 months) after first-line therapy is a poor prognostic factor but does not preclude cure with appropriately intensified salvage therapy.', 3),
('d6000000-0000-0000-0000-000000000026', 'Cytokine release syndrome typically occurs in the days following CAR-T cell infusion and presents with fever, hypotension, and hypoxia due to massive cytokine release, particularly IL-6.', 1),
('d6000000-0000-0000-0000-000000000026', 'Tocilizumab, an IL-6 receptor antagonist, is first-line treatment for CRS with haemodynamic or respiratory compromise; corticosteroids are added for severe or refractory CRS or when neurotoxicity (ICANS) is present.', 2),
('d6000000-0000-0000-0000-000000000026', 'Infection should still be considered and covered empirically given overlapping presentation, but recognition of CRS is essential to avoid delaying targeted treatment.', 3),
('d6000000-0000-0000-0000-000000000027', 'Burkitt lymphoma is very high risk for tumour lysis syndrome given its rapid proliferation and chemosensitivity; high-risk patients should receive aggressive IV hydration and rasburicase before and during initial chemotherapy.', 1),
('d6000000-0000-0000-0000-000000000027', 'Rasburicase is preferred over allopurinol in high-risk TLS as it rapidly degrades existing uric acid, whereas allopurinol only blocks further xanthine oxidase-mediated urate production.', 2),
('d6000000-0000-0000-0000-000000000027', 'Tumour lysis syndrome is characterised by hyperkalaemia, hyperphosphataemia, hyperuricaemia and hypocalcaemia, with risk of acute kidney injury and arrhythmia; rasburicase is contraindicated in G6PD deficiency due to haemolysis risk.', 3),
('d6000000-0000-0000-0000-000000000028', 'Philadelphia chromosome-positive ALL requires the addition of a tyrosine kinase inhibitor to chemotherapy, which has dramatically improved remission rates and survival compared with chemotherapy alone.', 1),
('d6000000-0000-0000-0000-000000000028', 'Allogeneic stem cell transplantation in first remission is often considered for Ph+ ALL given its historically aggressive course, though outcomes with TKI-chemotherapy combinations continue to improve.', 2),
('d6000000-0000-0000-0000-000000000028', 'Ongoing molecular (BCR-ABL1 transcript) monitoring guides continued TKI therapy and detection of relapse or resistance mutations.', 3),
('d6000000-0000-0000-0000-000000000029', 'Myeloma-related hypercalcaemia and renal impairment require prompt, aggressive supportive management alongside rapid initiation of effective anti-myeloma therapy to reverse the underlying process.', 1),
('d6000000-0000-0000-0000-000000000029', 'Zoledronic acid requires dose reduction or avoidance in significant renal impairment; denosumab, not renally cleared, is an alternative for hypercalcaemia of malignancy in this setting.', 2),
('d6000000-0000-0000-0000-000000000029', 'Daratumumab-based regimens are effective in relapsed/refractory myeloma, including after prior proteasome inhibitor/immunomodulatory drug exposure.', 3),
('d6000000-0000-0000-0000-000000000030', 'CLL with del(17p) and/or TP53 mutation responds poorly to standard chemoimmunotherapy, as the DNA-damage response pathway required for chemotherapy-induced apoptosis is disrupted; targeted agents are preferred first-line regardless of fitness.', 1),
('d6000000-0000-0000-0000-000000000030', 'Testing for del(17p)/TP53 mutation status should be performed before first-line treatment selection in CLL, as it fundamentally changes the recommended regimen.', 2),
('d6000000-0000-0000-0000-000000000030', 'Allogeneic stem cell transplant remains a consideration for young, fit patients with high-risk CLL who relapse after targeted therapy, given potential for long-term disease control.', 3),
('d6000000-0000-0000-0000-000000000031', 'Risk stratification in PV (age over 60 years and/or history of thrombosis defines high risk) determines the need for cytoreductive therapy in addition to venesection and low-dose aspirin.', 1),
('d6000000-0000-0000-0000-000000000031', 'Hydroxycarbamide is standard first-line cytoreductive therapy in high-risk PV; interferon-alpha is an alternative, particularly favoured in younger patients.', 2),
('d6000000-0000-0000-0000-000000000031', 'Maintaining strict haematocrit control below 0.45 has been shown to reduce cardiovascular events and thrombosis in PV.', 3),
('d6000000-0000-0000-0000-000000000032', 'Hydroxycarbamide is teratogenic and must be stopped when pregnancy is confirmed; interferon-alpha is the preferred cytoreductive agent in pregnancy if needed, as it does not cross the placenta in significant amounts.', 1),
('d6000000-0000-0000-0000-000000000032', 'Low-dose aspirin is generally continued throughout pregnancy in ET to reduce the risk of placental vascular complications, miscarriage, and thrombosis.', 2),
('d6000000-0000-0000-0000-000000000032', 'CALR-mutated ET generally carries a lower thrombosis risk than JAK2-mutated ET, but pregnancy itself is a prothrombotic state requiring careful multidisciplinary management regardless of mutation status.', 3),
('d6000000-0000-0000-0000-000000000033', 'Ruxolitinib, a JAK1/2 inhibitor, is effective for reducing spleen size and improving constitutional symptoms in intermediate/high-risk myelofibrosis, and is preferred over hydroxycarbamide for these indications.', 1),
('d6000000-0000-0000-0000-000000000033', 'Allogeneic stem cell transplant remains the only potentially curative option for myelofibrosis but is reserved for fit, higher-risk patients given significant transplant-related morbidity/mortality.', 2),
('d6000000-0000-0000-0000-000000000033', 'Splenectomy in myelofibrosis carries substantial perioperative risk (bleeding, thrombosis, infection) and is reserved for specific refractory complications rather than first-line symptom management.', 3),
('d6000000-0000-0000-0000-000000000034', 'Polycythaemia vera can transform over time into post-PV myelofibrosis, characterised by anaemia, progressive splenomegaly, a leucoerythroblastic blood film, and marrow fibrosis, requiring a shift from PV-specific therapy to myelofibrosis-directed management.', 1),
('d6000000-0000-0000-0000-000000000034', 'Ongoing surveillance of PV/ET patients should include monitoring for the recognised risk of transformation to myelofibrosis and, less commonly, acute leukaemia.', 2),
('d6000000-0000-0000-0000-000000000034', 'Management of post-PV myelofibrosis follows the same risk-stratified pathways as primary myelofibrosis, including consideration of JAK inhibitors or allogeneic transplant in eligible patients.', 3),
('d6000000-0000-0000-0000-000000000035', 'Revised risk stratification models for ET (e.g., IPSET-thrombosis) incorporate driver mutation status alongside age and thrombosis history, recognising that JAK2 V617F-mutated ET carries a higher thrombotic risk than CALR-mutated disease.', 1),
('d6000000-0000-0000-0000-000000000035', 'Extreme thrombocytosis in ET can be associated with acquired von Willebrand syndrome, increasing bleeding risk rather than thrombosis risk, altering antiplatelet therapy decisions at very high platelet counts.', 2),
('d6000000-0000-0000-0000-000000000035', 'Individualised risk-adapted therapy in ET depends on age, thrombosis history, cardiovascular risk factors, and driver mutation status rather than platelet count alone.', 3),
('d6000000-0000-0000-0000-000000000036', 'Budd-Chiari syndrome and other unusual-site (splanchnic) thromboses are strongly associated with underlying myeloproliferative neoplasms, and JAK2 V617F testing should be performed even when blood counts appear only mildly abnormal.', 1),
('d6000000-0000-0000-0000-000000000036', 'Management requires both anticoagulation for the thrombosis and cytoreductive therapy targeting the underlying MPN to reduce ongoing thrombotic risk.', 2),
('d6000000-0000-0000-0000-000000000036', 'Multidisciplinary management (haematology and hepatology) is required, with liver transplantation reserved for fulminant or treatment-refractory liver failure.', 3),
('d6000000-0000-0000-0000-000000000037', 'Blast crisis is defined by a peripheral or marrow blast percentage meeting WHO criteria and represents transformation to an acute leukaemia-like phase of CML, requiring lineage-directed induction chemotherapy combined with a potent TKI.', 1),
('d6000000-0000-0000-0000-000000000037', 'Allogeneic stem cell transplant offers the best chance of long-term disease control in blast crisis but should ideally be performed after achieving a return to chronic phase/remission with combination therapy.', 2),
('d6000000-0000-0000-0000-000000000037', 'New clonal cytogenetic evolution alongside rising blast counts indicates disease progression and resistance, warranting mutation analysis to guide TKI selection.', 3),
('d6000000-0000-0000-0000-000000000038', 'Abrupt discontinuation of ruxolitinib can precipitate a severe cytokine rebound (withdrawal) syndrome, with rapid return or worsening of splenomegaly, high fever, and haemodynamic instability mimicking sepsis or disease progression.', 1),
('d6000000-0000-0000-0000-000000000038', 'Patients should be counselled never to abruptly stop ruxolitinib; when discontinuation is necessary, a tapering approach with corticosteroid cover is often used.', 2),
('d6000000-0000-0000-0000-000000000038', 'Prompt reinstitution of ruxolitinib is the key management step for withdrawal syndrome, alongside supportive care and exclusion of intercurrent infection or disease transformation.', 3),
('d6000000-0000-0000-0000-000000000039', 'Advanced systemic mastocytosis with the KIT D816V mutation, present in the majority of cases, is resistant to imatinib; midostaurin and newer avapritinib have activity against KIT D816V and are used in advanced disease with organ dysfunction.', 1),
('d6000000-0000-0000-0000-000000000039', 'C-findings (cytopenias, hepatosplenomegaly with organ dysfunction, osteolysis, malabsorption) define advanced/aggressive systemic mastocytosis requiring targeted therapy beyond symptomatic mediator-blockade.', 2),
('d6000000-0000-0000-0000-000000000039', 'Symptomatic management (antihistamines, mast cell stabilisers, trigger avoidance) remains important adjunctively but does not treat the underlying clonal disease burden in advanced disease.', 3),
('d6000000-0000-0000-0000-000000000040', 'Ruxolitinib is licensed as second-line therapy for polycythaemia vera in patients resistant to or intolerant of hydroxycarbamide, providing effective haematocrit control and improvement of associated symptoms.', 1),
('d6000000-0000-0000-0000-000000000040', $x$Hydroxycarbamide-induced mucocutaneous toxicity, including leg ulcers, is a recognised reason to switch cytoreductive agents rather than escalate the causative drug's dose.$x$, 2),
('d6000000-0000-0000-0000-000000000040', 'Interferon-alpha is another alternative second-line cytoreductive option in PV, particularly considered in younger patients, though ruxolitinib is specifically indicated for hydroxycarbamide resistance/intolerance.', 3),
('d6000000-0000-0000-0000-000000000041', 'TACO typically presents with hypertension, acute pulmonary oedema, and a raised BNP relative to baseline, especially in patients with pre-existing cardiac dysfunction, renal impairment, or in the elderly; management involves stopping the transfusion, diuresis, and oxygen.', 1),
('d6000000-0000-0000-0000-000000000041', 'TRALI classically presents with hypotension and acute non-cardiogenic pulmonary oedema within 6 hours of transfusion, without a significant BNP rise, and is managed with supportive respiratory care rather than diuretics.', 2),
('d6000000-0000-0000-0000-000000000041', 'Distinguishing TACO from TRALI is clinically important as their management differs substantially, since diuresis could worsen hypotension in TRALI.', 3),
('d6000000-0000-0000-0000-000000000042', 'Massive transfusion protocols use a balanced ratio (approximately 1:1:1) of red cells, FFP, and platelets to replicate whole blood and reduce dilutional coagulopathy in major trauma haemorrhage.', 1),
('d6000000-0000-0000-0000-000000000042', 'Early tranexamic acid, given within 3 hours of injury, reduces mortality in traumatic haemorrhage and should not be withheld due to theoretical thrombotic concerns.', 2),
('d6000000-0000-0000-0000-000000000042', 'Excessive crystalloid resuscitation prior to haemorrhage control worsens coagulopathy, hypothermia, and acidosis; permissive hypotension and early blood product-based resuscitation are preferred until definitive haemorrhage control.', 3),
('d6000000-0000-0000-0000-000000000043', 'Acute haemolytic transfusion reactions, most commonly due to ABO incompatibility from clerical/identification errors, present with fever, loin/back pain, hypotension, and haemoglobinuria typically within minutes of starting the transfusion, and constitute a medical emergency requiring immediate cessation.', 1),
('d6000000-0000-0000-0000-000000000043', 'Immediate management includes maintaining IV access with saline to support renal perfusion, sending samples to the blood bank (repeat group and screen, direct antiglobulin test), and monitoring for acute kidney injury and DIC.', 2),
('d6000000-0000-0000-0000-000000000043', 'Meticulous bedside identity checks before transfusion are the key preventive measure, as clerical error remains the leading cause of ABO-incompatible transfusion reactions.', 3),
('d6000000-0000-0000-0000-000000000044', 'Delayed haemolytic transfusion reactions occur days to weeks after transfusion, typically in previously alloimmunised patients whose antibody titres have fallen below detectable levels at the time of crossmatch, but rise rapidly (anamnestic response) on re-exposure to the corresponding antigen.', 1),
('d6000000-0000-0000-0000-000000000044', 'Presentation includes unexplained falling haemoglobin, jaundice, and a positive direct antiglobulin test with a newly identified alloantibody, occurring days after an apparently compatible transfusion.', 2),
('d6000000-0000-0000-0000-000000000044', 'Multiply transfused patients are at higher risk of alloimmunisation and delayed haemolytic reactions, underscoring the importance of extended red cell phenotyping/antibody history where possible.', 3),
('d6000000-0000-0000-0000-000000000045', 'Febrile non-haemolytic transfusion reactions, from cytokines released by leucocytes/platelets during storage, are common, generally mild, and managed with antipyretics and slowing/pausing the transfusion, but more serious causes of fever must always be actively excluded first.', 1),
('d6000000-0000-0000-0000-000000000045', 'Platelet concentrates are stored at room temperature and carry a higher risk of bacterial contamination compared with refrigerated red cells, so unexplained fever during platelet transfusion warrants a lower threshold for considering sepsis.', 2),
('d6000000-0000-0000-0000-000000000045', 'Leucodepletion of blood components has reduced but not eliminated the incidence of febrile non-haemolytic transfusion reactions.', 3),
('d6000000-0000-0000-0000-000000000046', 'Irradiated blood components are required for patients at risk of transfusion-associated graft-versus-host disease, including those treated with purine analogues, Hodgkin lymphoma patients, patients with severe congenital immunodeficiencies, and stem cell transplant recipients.', 1),
('d6000000-0000-0000-0000-000000000046', $x$Transfusion-associated GVHD occurs when viable donor T-lymphocytes engraft and attack the immunocompromised recipient's tissues, and is almost universally fatal; irradiation inactivates donor lymphocytes to prevent this.$x$, 2),
('d6000000-0000-0000-0000-000000000046', 'The irradiation requirement is distinct from other special requirements, such as leucodepletion for CMV risk reduction or washing for allergic reactions, each addressing a different transfusion risk.', 3),
('d6000000-0000-0000-0000-000000000047', 'Intrauterine and neonatal exchange transfusions require irradiated, CMV-safe (seronegative and/or leucodepleted), fresh red cell components due to the heightened risk of transfusion-associated GVHD and CMV transmission in the immunologically immature fetus/neonate.', 1),
('d6000000-0000-0000-0000-000000000047', 'The transfused unit must be matched to avoid the specific antigen(s) implicated in the alloimmunisation in addition to routine ABO/RhD compatibility.', 2),
('d6000000-0000-0000-0000-000000000047', 'Red cell alloimmunisation causing fetal anaemia is monitored using serial middle cerebral artery Doppler peak systolic velocity, guiding the timing of intrauterine transfusion.', 3),
('d6000000-0000-0000-0000-000000000048', 'Any potentially sensitising event in an RhD-negative pregnant woman warrants additional anti-D immunoglobulin, ideally administered within 72 hours, separate from routine antenatal prophylactic dosing.', 1),
('d6000000-0000-0000-0000-000000000048', 'A Kleihauer test quantifies the volume of fetomaternal haemorrhage and guides whether a standard or higher dose of anti-D immunoglobulin is required.', 2),
('d6000000-0000-0000-0000-000000000048', 'Prompt anti-D administration after sensitising events reduces the risk of maternal alloimmunisation against the RhD antigen, which could cause haemolytic disease of the fetus/newborn in this or future pregnancies.', 3),
('d6000000-0000-0000-0000-000000000049', 'Immune-mediated platelet transfusion refractoriness, typically from HLA class I alloimmunisation from prior transfusions or pregnancy, should be suspected when corrected count increments remain low across multiple transfusions in the absence of non-immune causes.', 1),
('d6000000-0000-0000-0000-000000000049', $x$The corrected count increment is used to objectively assess platelet transfusion response, adjusting for the platelet dose transfused and the patient's body surface area.$x$, 2),
('d6000000-0000-0000-0000-000000000049', 'HLA-matched or crossmatch-compatible platelet units can overcome immune refractoriness once significant non-immune causes have been excluded and alloantibodies confirmed.', 3),
('d6000000-0000-0000-0000-000000000050', 'Hyperhaemolysis syndrome is a life-threatening transfusion complication seen particularly in sickle cell disease, where post-transfusion haemoglobin falls below the pre-transfusion baseline due to destruction of both transfused and autologous red cells, often without a newly identifiable alloantibody.', 1),
('d6000000-0000-0000-0000-000000000050', 'Further transfusion can worsen hyperhaemolysis and should generally be avoided or given only under specialist guidance for life-threatening anaemia; management instead focuses on immunosuppression.', 2),
('d6000000-0000-0000-0000-000000000050', 'A history of a similar prior post-transfusion episode should raise suspicion for hyperhaemolysis syndrome and prompt early haematology involvement before further transfusion is considered.', 3);
